import type { LessonContent } from './types';

function pbi(day: number, topic: string, topicName: string, title: string, obj: string[], steps: string[], hint: string, hintCode: string, solDesc: string, solCode: string, success: string[], takeaway: string): LessonContent {
  return { topicSlug: topic, topicName, domainSlug: 'power-bi', dayNumber: day, title, duration: 30, objectives: obj, steps: steps.map(s => ({ instruction: s })), hint: { description: hint, code: hintCode }, fullSolution: { description: solDesc, code: solCode }, successCriteria: success, keyTakeaway: takeaway };
}

export const powerBiLessons: LessonContent[] = [
  // ── Power Query Fundamentals (11 lessons) ─────────────────────────────
  pbi(1,'power-query','Power Query Fundamentals','Connecting to Data Sources',['Understand Power Query Editor interface','Connect to CSV, Excel, and SQL sources','Apply basic column transformations'],['Open Power BI Desktop → Get Data','Connect to a CSV file and preview data','Use the Navigator pane to select tables','Open Power Query Editor','Rename columns using double-click','Change data types for date and number columns','Click Close & Apply'],
    'Power Query Editor is where all data shaping happens before it reaches the model. Always check data types after import.',
    'let\n  Source = Csv.Document(File.Contents("sales.csv")),\n  Promoted = Table.PromoteHeaders(Source),\n  Types = Table.TransformColumnTypes(Promoted, {{"Date", type date}, {"Amount", type number}})\nin\n  Types',
    'Complete M code for connecting to CSV with type transformations.',
    'let\n  Source = Csv.Document(\n    File.Contents("C:\\Data\\sales.csv"),\n    [Delimiter=",", Encoding=65001]\n  ),\n  Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars=true]),\n  Types = Table.TransformColumnTypes(Promoted, {\n    {"OrderID", Int64.Type},\n    {"Date", type date},\n    {"Product", type text},\n    {"Amount", Currency.Type},\n    {"Region", type text}\n  }),\n  Filtered = Table.SelectRows(Types, each [Amount] > 0)\nin\n  Filtered',
    ['Connected to at least 2 data sources','All columns have correct data types','Null/empty rows filtered','Query loads without errors'],'Power Query is your ETL engine — clean data here so your model stays simple.'),

  pbi(2,'power-query','Power Query Fundamentals','Column Transformations & Splits',['Split columns by delimiter','Create conditional columns','Apply text transformations'],['Import a dataset with combined fields','Split Name column into First/Last','Extract domain from email using Text.AfterDelimiter','Add conditional column for region grouping','Replace null values with defaults','Remove original combined columns','Verify row count unchanged'],
    'Use Add Column → Conditional Column for if/then logic. Text.BeforeDelimiter and Text.AfterDelimiter are your friends for parsing.',
    'Table.AddColumn(Source, "Domain",\n  each Text.AfterDelimiter([Email], "@")\n)',
    'Full transform with splits, conditionals, and cleanup.',
    'let\n  Source = Excel.Workbook(File.Contents("employees.xlsx")),\n  Data = Source{[Name="Sheet1"]}[Data],\n  Promoted = Table.PromoteHeaders(Data),\n  SplitName = Table.SplitColumn(Promoted, "FullName",\n    Splitter.SplitTextByEachDelimiter({" "}, QuoteStyle.None, false),\n    {"FirstName", "LastName"}),\n  Domain = Table.AddColumn(SplitName, "EmailDomain",\n    each Text.AfterDelimiter([Email], "@"), type text),\n  Region = Table.AddColumn(Domain, "RegionGroup",\n    each if [State] = "CA" or [State] = "WA" then "West"\n    else if [State] = "NY" or [State] = "NJ" then "East"\n    else "Other", type text),\n  Clean = Table.ReplaceValue(Region, null, "Unknown",\n    Replacer.ReplaceValue, {"Department"})\nin\n  Clean',
    ['Name split into First/Last correctly','Email domain extracted','Conditional column logic works','No nulls in required fields'],'Transform columns at the source — never fix data problems in DAX.'),

  pbi(3,'power-query','Power Query Fundamentals','Merging and Appending Queries',['Merge queries using join types','Append queries for union operations','Handle mismatched schemas'],['Create two queries: Orders and Customers','Merge Orders with Customers on CustomerID','Select join type: Left Outer','Expand the merged column to get Customer Name','Append Q1 and Q2 sales tables','Handle column name mismatches','Verify merge produced no extra rows'],
    'Left Outer join keeps all rows from the first table. Use Table.NestedJoin for merge, Table.Combine for append.',
    'Table.NestedJoin(\n  Orders, {"CustomerID"},\n  Customers, {"ID"},\n  "Cust", JoinKind.LeftOuter\n)',
    'Complete merge and append with error handling.',
    'let\n  Orders = Table.FromRecords({\n    [OrderID=1, CustID=101, Amount=500],\n    [OrderID=2, CustID=102, Amount=300],\n    [OrderID=3, CustID=999, Amount=150]\n  }),\n  Customers = Table.FromRecords({\n    [CustID=101, Name="Acme Corp", Tier="Gold"],\n    [CustID=102, Name="Beta Inc", Tier="Silver"]\n  }),\n  Merged = Table.NestedJoin(Orders, {"CustID"},\n    Customers, {"CustID"}, "Customer", JoinKind.LeftOuter),\n  Expanded = Table.ExpandTableColumn(Merged, "Customer",\n    {"Name", "Tier"}, {"CustomerName", "CustomerTier"}),\n  Filled = Table.ReplaceValue(Expanded, null, "Unknown",\n    Replacer.ReplaceValue, {"CustomerName", "CustomerTier"})\nin\n  Filled',
    ['Merge returns correct row count','Unmatched rows show null/default','Append combines all rows','No duplicate columns'],'Merges join horizontally (add columns), appends stack vertically (add rows).'),

  pbi(4,'power-query','Power Query Fundamentals','Error Handling & Data Quality',['Handle errors in Power Query','Profile data for quality issues','Create error logging'],['Enable Column Profile in View tab','Check column quality, distribution, and profile','Identify columns with errors','Use try...otherwise for error handling','Replace errors with default values','Create an error log query','Document data quality findings'],
    'try [Column] otherwise null catches errors without breaking the query. Column Profile shows value distribution at a glance.',
    'Table.AddColumn(Source, "SafeAmount",\n  each try Number.From([Amount]) otherwise 0\n)',
    'Comprehensive error handling with logging.',
    'let\n  Source = Table.FromRecords({\n    [ID=1, Amount="500", Date="2025-01-15"],\n    [ID=2, Amount="bad", Date="2025-02-01"],\n    [ID=3, Amount="300", Date="invalid"],\n    [ID=4, Amount="750", Date="2025-03-10"]\n  }),\n  SafeAmount = Table.AddColumn(Source, "ParsedAmount",\n    each try Number.From([Amount]) otherwise null, type number),\n  SafeDate = Table.AddColumn(SafeAmount, "ParsedDate",\n    each try Date.From([Date]) otherwise null, type date),\n  ErrorLog = Table.SelectRows(SafeDate,\n    each [ParsedAmount] = null or [ParsedDate] = null),\n  CleanData = Table.SelectRows(SafeDate,\n    each [ParsedAmount] <> null and [ParsedDate] <> null)\nin\n  CleanData',
    ['Errors caught without query failure','Error log captures bad rows','Clean data has zero errors','Column profile reviewed'],'Data quality is a feature — build error handling into every query.'),

  pbi(5,'power-query','Power Query Fundamentals','Custom Functions & Parameters',['Create reusable M functions','Use query parameters for dynamic sources','Apply functions across tables'],['Create a parameter for file path','Write a function to clean a single table','Invoke custom function on multiple files','Use Folder.Files to process a directory','Add parameter for date filter','Test function with different inputs','Document function purpose and parameters'],
    'Parameters make queries portable. Custom functions let you apply the same transforms to multiple tables.',
    'let\n  CleanTable = (tbl as table) as table =>\n    let\n      Trimmed = Table.TransformColumns(tbl,\n        {{"Name", Text.Trim}})\n    in\n      Trimmed\nin\n  CleanTable',
    'Parameterized folder processing with custom function.',
    'let\n  FolderPath = Excel.CurrentWorkbook(){[Name="ParamPath"]}[Content]{0}[Column1],\n  Files = Folder.Files(FolderPath),\n  CsvFiles = Table.SelectRows(Files, each [Extension] = ".csv"),\n  CleanFile = (filePath as text) as table =>\n    let\n      Raw = Csv.Document(File.Contents(filePath)),\n      Promoted = Table.PromoteHeaders(Raw),\n      Typed = Table.TransformColumnTypes(Promoted, {\n        {"Date", type date}, {"Amount", type number}\n      }),\n      Filtered = Table.SelectRows(Typed, each [Amount] > 0)\n    in\n      Filtered,\n  AddData = Table.AddColumn(CsvFiles, "Data",\n    each CleanFile([Folder Path] & [Name])),\n  Combined = Table.Combine(AddData[Data])\nin\n  Combined',
    ['Parameter controls source path','Function processes any table','Folder import works for multiple files','Consistent output schema'],'Functions turn one-off transforms into reusable building blocks.'),

  pbi(6,'power-query','Power Query Fundamentals','Query Folding & Performance',['Understand query folding','Identify steps that break folding','Optimize query performance'],['Right-click a step → View Native Query','Identify which steps fold to source','Move filterable steps before unfoldable ones','Remove unnecessary columns early','Use Table.Buffer strategically','Compare load times before/after optimization','Document which steps fold'],
    'Query folding pushes transforms to the data source (SQL). Steps like adding custom columns or merging break folding.',
    '-- Right-click step → "View Native Query" shows:\nSELECT [Date], [Amount], [Region]\nFROM [Sales]\nWHERE [Amount] > 0\n-- If grayed out, folding is broken at that step',
    'Optimized query with folding preserved.',
    'let\n  // Step 1: Connect (folds)\n  Source = Sql.Database("server", "db"),\n  Sales = Source{[Schema="dbo", Item="Sales"]}[Data],\n  // Step 2: Filter early (folds → becomes WHERE clause)\n  Filtered = Table.SelectRows(Sales, each [Year] >= 2024),\n  // Step 3: Select columns early (folds → becomes SELECT)\n  Selected = Table.SelectColumns(Filtered,\n    {"OrderID", "Date", "Product", "Amount", "Region"}),\n  // Step 4: Type changes (folds)\n  Typed = Table.TransformColumnTypes(Selected, {\n    {"Date", type date}, {"Amount", Currency.Type}\n  }),\n  // Step 5: Custom column (breaks folding — do last)\n  WithMargin = Table.AddColumn(Typed, "Margin",\n    each [Amount] * 0.35, Currency.Type)\nin\n  WithMargin',
    ['Native query visible for key steps','Filters applied before custom columns','Unnecessary columns removed early','Load time improved'],'Query folding is the #1 performance lever — filter and select before you transform.'),

  pbi(7,'power-query','Power Query Fundamentals','Pivoting & Unpivoting Data',['Pivot columns to rows and back','Reshape data for analysis','Handle dynamic column names'],['Import a cross-tab report (months as columns)','Select month columns → Unpivot','Rename to Date and Value columns','Import a long-format table','Pivot rows to columns','Handle null values in pivoted data','Compare row counts before/after'],
    'Unpivot turns wide data narrow (columns→rows). Pivot turns narrow data wide (rows→columns). Unpivot is almost always the right first step for cross-tab reports.',
    'Table.UnpivotOtherColumns(Source,\n  {"Product", "Region"}, "Month", "Sales"\n)',
    'Complete reshape workflow.',
    'let\n  Source = Table.FromRecords({\n    [Product="Widget", Jan=100, Feb=120, Mar=95],\n    [Product="Gadget", Jan=200, Feb=180, Mar=210],\n    [Product="Gizmo", Jan=50, Feb=65, Mar=70]\n  }),\n  Unpivoted = Table.UnpivotOtherColumns(Source,\n    {"Product"}, "Month", "Sales"),\n  Typed = Table.TransformColumnTypes(Unpivoted, {\n    {"Sales", Int64.Type}\n  }),\n  MonthOrder = Table.AddColumn(Typed, "MonthNum",\n    each List.PositionOf(\n      {"Jan","Feb","Mar","Apr","May","Jun",\n       "Jul","Aug","Sep","Oct","Nov","Dec"}, [Month]) + 1),\n  Sorted = Table.Sort(MonthOrder, {{"Product", Order.Ascending}, {"MonthNum", Order.Ascending}})\nin\n  Sorted',
    ['Cross-tab reshaped to rows','Column names become values','No data lost in transform','Sorted logically'],'Unpivot is the most common reshape — learn it cold.'),

  pbi(8,'power-query','Power Query Fundamentals','Date Table Generation in M',['Generate a complete date table in M','Add fiscal year and quarter columns','Create date intelligence columns'],['Define start and end dates','Generate a list of dates with List.Dates','Convert to table and set types','Add Year, Month, Quarter columns','Add Fiscal Year (July start)','Add WeekOfYear and DayOfWeek','Mark as Date Table in the model'],
    'Every time-intelligence DAX function requires a contiguous date table marked as such in the model.',
    'let\n  Dates = List.Dates(#date(2024,1,1), 730, #duration(1,0,0,0)),\n  Table = Table.FromList(Dates, Splitter.SplitByNothing(), {"Date"})\nin\n  Table',
    'Full date table with fiscal year and intelligence columns.',
    'let\n  StartDate = #date(2024, 1, 1),\n  EndDate = #date(2026, 12, 31),\n  Days = Duration.Days(EndDate - StartDate) + 1,\n  DateList = List.Dates(StartDate, Days, #duration(1,0,0,0)),\n  ToTable = Table.FromList(DateList, Splitter.SplitByNothing(), type table [Date = date]),\n  Year = Table.AddColumn(ToTable, "Year", each Date.Year([Date]), Int64.Type),\n  Month = Table.AddColumn(Year, "Month", each Date.Month([Date]), Int64.Type),\n  MonthName = Table.AddColumn(Month, "MonthName", each Date.ToText([Date], "MMM"), type text),\n  Quarter = Table.AddColumn(MonthName, "Quarter", each "Q" & Text.From(Date.QuarterOfYear([Date])), type text),\n  FiscalMonth = Table.AddColumn(Quarter, "FiscalMonth", each if [Month] >= 7 then [Month] - 6 else [Month] + 6, Int64.Type),\n  FiscalYear = Table.AddColumn(FiscalMonth, "FiscalYear", each if [Month] >= 7 then [Year] + 1 else [Year], Int64.Type),\n  FiscalQuarter = Table.AddColumn(FiscalYear, "FiscalQuarter", each "FQ" & Text.From(Number.RoundUp([FiscalMonth] / 3)), type text),\n  WeekNum = Table.AddColumn(FiscalQuarter, "WeekOfYear", each Date.WeekOfYear([Date]), Int64.Type),\n  DayName = Table.AddColumn(WeekNum, "DayOfWeek", each Date.DayOfWeekName([Date]), type text),\n  IsWeekend = Table.AddColumn(DayName, "IsWeekend", each Date.DayOfWeek([Date]) >= 5, type logical)\nin\n  IsWeekend',
    ['Date table is contiguous (no gaps)','Fiscal year starts July','Quarter and week columns present','Marked as Date Table in model'],'A proper date table is the foundation of all time intelligence in Power BI.'),

  pbi(9,'power-query','Power Query Fundamentals','Incremental Refresh Setup',['Configure incremental refresh policies','Define RangeStart and RangeEnd parameters','Understand partition management'],['Create RangeStart and RangeEnd parameters (DateTime)','Filter source query using these parameters','Configure refresh policy in model settings','Set historical period (e.g. 3 years)','Set incremental period (e.g. 30 days)','Publish to Power BI Service','Monitor partition sizes'],
    'RangeStart and RangeEnd must be DateTime parameters that filter the source query. Power BI Service manages partitions automatically.',
    'let\n  Source = Sql.Database("server", "db"),\n  Sales = Source{[Schema="dbo",Item="FactSales"]}[Data],\n  Filtered = Table.SelectRows(Sales,\n    each [OrderDate] >= RangeStart and [OrderDate] < RangeEnd)\nin\n  Filtered',
    'Incremental refresh configuration with partition strategy.',
    'let\n  // RangeStart and RangeEnd are DateTime parameters\n  // created via Manage Parameters in Power Query\n  Source = Sql.Database("analytics-server", "SalesDB"),\n  FactSales = Source{[Schema="dbo", Item="FactSales"]}[Data],\n  // Critical: filter MUST use >= RangeStart and < RangeEnd\n  Filtered = Table.SelectRows(FactSales,\n    each [OrderDate] >= RangeStart and [OrderDate] < RangeEnd),\n  Selected = Table.SelectColumns(Filtered, {\n    "OrderID", "OrderDate", "CustomerID", "ProductID",\n    "Quantity", "UnitPrice", "Discount", "TotalAmount"\n  }),\n  Typed = Table.TransformColumnTypes(Selected, {\n    {"OrderDate", type datetime},\n    {"TotalAmount", Currency.Type}\n  })\nin\n  Typed\n// After publish: Model → Incremental Refresh\n// Store rows: 3 years | Refresh rows: 30 days\n// Optional: Detect data changes column = [ModifiedDate]',
    ['RangeStart/RangeEnd parameters created','Filter uses >= start and < end','Query folds the date filter','Refresh policy configured'],'Incremental refresh turns hours-long refreshes into minutes by only updating recent data.'),

  pbi(10,'power-query','Power Query Fundamentals','Advanced M: List and Record Functions',['Use List.Generate for complex sequences','Apply Record functions for dynamic access','Combine List and Table operations'],['Use List.Generate to create a Fibonacci sequence','Apply List.Accumulate to running totals','Use Record.FieldValues for dynamic column access','Combine List.Transform with Table.AddColumn','Create pagination with List.Generate for API calls','Test with different input sizes','Benchmark performance'],
    'List.Generate is M\'s loop equivalent. List.Accumulate is reduce/fold. Both are powerful for complex transformations.',
    'List.Generate(\n  () => [i=0, val=1],\n  each [i] < 10,\n  each [i=[i]+1, val=[val]*2],\n  each [val]\n)',
    'Advanced M patterns including pagination.',
    'let\n  // Fibonacci with List.Generate\n  Fib = List.Generate(\n    () => [i=0, a=0, b=1],\n    each [i] < 20,\n    each [i=[i]+1, a=[b], b=[a]+[b]],\n    each [a]\n  ),\n  // Running total with List.Accumulate\n  Values = {10, 20, 15, 30, 25},\n  RunningTotal = List.Accumulate(\n    Values, {}, (state, current) =>\n      state & {List.Sum(state) + current}\n  ),\n  // API Pagination pattern\n  GetPage = (pageNum as number) as table =>\n    let\n      url = "https://api.example.com/data?page=" & Text.From(pageNum) & "&size=100",\n      // Simulated response\n      response = Table.FromRecords({\n        [id = pageNum * 100 + 1, value = "item"]\n      })\n    in response,\n  AllPages = List.Generate(\n    () => [page=1, data=GetPage(1), hasMore=true],\n    each [hasMore] and [page] <= 5,\n    each [page=[page]+1, data=GetPage([page]+1),\n          hasMore=Table.RowCount([data]) = 100],\n    each [data]\n  ),\n  Combined = Table.Combine(AllPages)\nin\n  Combined',
    ['List.Generate produces correct sequence','Running totals accumulate correctly','Pagination fetches multiple pages','Results combine into single table'],'M is a functional language — List.Generate and List.Accumulate replace loops.'),

  pbi(11,'power-query','Power Query Fundamentals','Data Profiling & Documentation',['Use Column Profile for data exploration','Document data lineage','Create a data dictionary query'],['Enable Column Profile (entire dataset, not top 1000)','Review value distribution for each column','Identify columns with high cardinality','Check for pattern violations','Create a metadata query listing all columns and types','Document source-to-target mapping','Generate data quality report'],
    'Always change Column Profile from "Top 1000 rows" to "Entire dataset" in the status bar for accurate profiling.',
    'let\n  Source = Table.Schema(YourTable),\n  Selected = Table.SelectColumns(Source,\n    {"Name", "Kind", "IsNullable"})\nin\n  Selected',
    'Complete data dictionary generator.',
    'let\n  GetSchema = (tableName as text, tbl as table) as table =>\n    let\n      Schema = Table.Schema(tbl),\n      Selected = Table.SelectColumns(Schema, {\n        "Name", "Kind", "TypeName", "IsNullable"\n      }),\n      WithTable = Table.AddColumn(Selected, "TableName",\n        each tableName, type text),\n      WithStats = Table.AddColumn(WithTable, "UniqueValues",\n        each Table.RowCount(\n          Table.Distinct(Table.SelectColumns(tbl, {[Name]}))\n        ), Int64.Type),\n      WithNulls = Table.AddColumn(WithStats, "NullCount",\n        each List.Count(\n          List.Select(Table.Column(tbl, [Name]), each _ = null)\n        ), Int64.Type),\n      WithFill = Table.AddColumn(WithNulls, "FillRate",\n        each 1 - ([NullCount] / Table.RowCount(tbl)), Percentage.Type)\n    in\n      WithFill,\n  // Apply to your tables\n  SalesDict = GetSchema("Sales", Sales),\n  CustomersDict = GetSchema("Customers", Customers),\n  Combined = Table.Combine({SalesDict, CustomersDict})\nin\n  Combined',
    ['All tables profiled','Unique values counted','Null rates documented','Data dictionary exportable'],'Profile your data before you model it — assumptions are the root of bad dashboards.'),

  // ── DAX Formulas & Calculations (11 lessons) ─────────────────────────
  pbi(1,'dax','DAX Formulas & Calculations','Calculated Columns vs Measures',['Understand when to use each','Create basic calculated columns','Write your first measure'],['Create a calculated column: Profit = Sales - Cost','Create a measure: Total Sales = SUM(Sales[Amount])','Compare: column evaluated row-by-row, measure per visual','Check file size impact of calculated columns','Convert a calculated column to a measure','Test measure in a card visual','Test measure in a matrix with filters'],
    'Measures are almost always better. Calculated columns add to file size and refresh time. Use columns only when you need row-level values for filtering or sorting.',
    'Total Sales = SUM(Sales[Amount])\nProfit Margin = DIVIDE(SUM(Sales[Profit]), SUM(Sales[Revenue]), 0)',
    'Core measures with proper error handling.',
    'Total Sales = SUM(Sales[Amount])\n\nTotal Cost = SUM(Sales[Cost])\n\nTotal Profit = [Total Sales] - [Total Cost]\n\nProfit Margin % = \n  DIVIDE(\n    [Total Profit],\n    [Total Sales],\n    0  -- default if division by zero\n  )\n\nAvg Order Value = \n  DIVIDE(\n    [Total Sales],\n    DISTINCTCOUNT(Sales[OrderID]),\n    0\n  )\n\n-- Calculated column (only when needed for filtering):\nOrder Size = \n  SWITCH(\n    TRUE(),\n    Sales[Amount] >= 1000, "Large",\n    Sales[Amount] >= 100, "Medium",\n    "Small"\n  )',
    ['Measure returns correct total','Measure responds to filter context','Calculated column shows per row','DIVIDE handles zero denominator'],'Default to measures. Use calculated columns only when you need to filter or sort by the result.'),

  pbi(2,'dax','DAX Formulas & Calculations','CALCULATE & Filter Context',['Understand evaluation context','Use CALCULATE to modify filters','Apply multiple filter arguments'],['Write a measure without CALCULATE','Add CALCULATE with a single filter','Add multiple filter conditions','Use REMOVEFILTERS to ignore a slicer','Compare results with and without CALCULATE','Test in matrix to see filter context','Explain the result to a colleague'],
    'CALCULATE is the most important DAX function. It evaluates an expression in a modified filter context. Each filter argument is ANDed together.',
    'Sales East = \n  CALCULATE(\n    [Total Sales],\n    Sales[Region] = "East"\n  )',
    'Advanced CALCULATE patterns.',
    'Sales East = \n  CALCULATE([Total Sales], Sales[Region] = "East")\n\n-- Multiple filters (AND)\nHigh Value East = \n  CALCULATE(\n    [Total Sales],\n    Sales[Region] = "East",\n    Sales[Amount] >= 500\n  )\n\n-- Override slicer (ignore user filter on Region)\nAll Region Sales = \n  CALCULATE(\n    [Total Sales],\n    REMOVEFILTERS(Sales[Region])\n  )\n\n-- % of Total pattern\nSales % of Total = \n  DIVIDE(\n    [Total Sales],\n    CALCULATE([Total Sales], REMOVEFILTERS(Sales[Region]))\n  )\n\n-- Keep one filter, remove others\nSales Keep Category = \n  CALCULATE(\n    [Total Sales],\n    REMOVEFILTERS(Sales),\n    VALUES(Sales[Category])  -- preserve Category filter\n  )',
    ['CALCULATE changes result vs plain measure','REMOVEFILTERS ignores slicer','% of Total sums to 100%','Multiple filters AND correctly'],'CALCULATE = take this measure, but evaluate it as if these filters were active.'),

  pbi(3,'dax','DAX Formulas & Calculations','Time Intelligence: YTD, QTD, MoM',['Apply TOTALYTD and TOTALQTD','Calculate month-over-month change','Build a rolling 3-month average'],['Create a proper Date table and mark it','Write YTD measure using TOTALYTD','Write QTD using TOTALQTD','Calculate prior month with PARALLELPERIOD','Calculate MoM % change','Build rolling 3-month average with DATESINPERIOD','Test all in a matrix by month'],
    'All time intelligence requires a Date table marked as such. TOTALYTD resets each January. Use DATESYTD for fiscal year start.',
    'Sales YTD = TOTALYTD([Total Sales], Dates[Date])\nSales PM = CALCULATE([Total Sales], PARALLELPERIOD(Dates[Date], -1, MONTH))',
    'Complete time intelligence measure library.',
    'Sales YTD = TOTALYTD([Total Sales], Dates[Date])\n\nSales QTD = TOTALQTD([Total Sales], Dates[Date])\n\nSales Prior Month = \n  CALCULATE(\n    [Total Sales],\n    PARALLELPERIOD(Dates[Date], -1, MONTH)\n  )\n\nMoM Change % = \n  VAR CurrentMonth = [Total Sales]\n  VAR PriorMonth = [Sales Prior Month]\n  RETURN\n    DIVIDE(CurrentMonth - PriorMonth, PriorMonth, 0)\n\nSales Prior Year = \n  CALCULATE([Total Sales], SAMEPERIODLASTYEAR(Dates[Date]))\n\nYoY Change % = \n  VAR Current = [Total Sales]\n  VAR Prior = [Sales Prior Year]\n  RETURN DIVIDE(Current - Prior, Prior, 0)\n\nRolling 3M Avg = \n  CALCULATE(\n    AVERAGEX(\n      DATESINPERIOD(Dates[Date], MAX(Dates[Date]), -3, MONTH),\n      [Total Sales]\n    )\n  )',
    ['YTD resets each year','MoM shows correct change','Prior year comparison works','Rolling average smooths trend'],'Time intelligence is why Power BI needs a proper date table — without it, these functions fail silently.'),

  pbi(4,'dax','DAX Formulas & Calculations','Iterator Functions: SUMX, AVERAGEX',['Understand row context in iterators','Use SUMX for row-level calculations','Combine iterators with CALCULATE'],['Compare SUM vs SUMX behavior','Write SUMX: row-by-row multiplication','Write AVERAGEX with a filtered table','Use MAXX and MINX for extremes','Combine SUMX with CALCULATE','Test with different granularities','Profile performance of iterators'],
    'Iterators (X functions) evaluate an expression row-by-row across a table, then aggregate. Use when you need per-row logic before aggregating.',
    'Weighted Revenue = \n  SUMX(Sales,\n    Sales[Quantity] * Sales[UnitPrice] * (1 - Sales[Discount])\n  )',
    'Iterator patterns for complex calculations.',
    'Net Revenue = \n  SUMX(\n    Sales,\n    Sales[Quantity] * Sales[UnitPrice] * (1 - Sales[Discount])\n  )\n\nAvg Margin by Product = \n  AVERAGEX(\n    Products,\n    DIVIDE(\n      CALCULATE([Total Sales]) - CALCULATE([Total Cost]),\n      CALCULATE([Total Sales]),\n      0\n    )\n  )\n\nTop Product Revenue = \n  MAXX(\n    Products,\n    CALCULATE([Total Sales])\n  )\n\n-- Weighted average (not simple average)\nWeighted Avg Price = \n  DIVIDE(\n    SUMX(Sales, Sales[Quantity] * Sales[UnitPrice]),\n    SUM(Sales[Quantity])\n  )\n\n-- Count with condition\nHigh Value Orders = \n  COUNTAX(\n    FILTER(Sales, Sales[Amount] > 500),\n    Sales[OrderID]\n  )',
    ['SUMX multiplies row-by-row correctly','AVERAGEX computes per-product average','Weighted average differs from simple','Iterator respects filter context'],'SUM aggregates a column. SUMX evaluates an expression per row then sums — use it when the formula needs row-level data.'),

  pbi(5,'dax','DAX Formulas & Calculations','Variables & SWITCH Patterns',['Use VAR for readability and performance','Apply SWITCH(TRUE()) for conditional logic','Build dynamic measures'],['Rewrite a complex measure using VAR','Show that VAR evaluates once (performance)','Use SWITCH(TRUE()) instead of nested IF','Create a dynamic measure driven by slicer','Use SELECTEDVALUE to read slicer selection','Test with different slicer selections','Compare performance with and without VAR'],
    'VAR evaluates once and can be reused. SWITCH(TRUE()) is more readable than nested IF. Use SELECTEDVALUE to make measures dynamic.',
    'VAR TotalSales = [Total Sales]\nVAR Target = 1000000\nRETURN IF(TotalSales >= Target, "On Track", "Behind")',
    'Dynamic measure with VAR and SWITCH.',
    'Performance Status = \n  VAR CurrentSales = [Total Sales]\n  VAR Target = [Sales Target]\n  VAR Achievement = DIVIDE(CurrentSales, Target, 0)\n  VAR Trend = [MoM Change %]\n  RETURN\n    SWITCH(\n      TRUE(),\n      Achievement >= 1.1, "Exceeding",\n      Achievement >= 0.95, "On Track",\n      Achievement >= 0.8 && Trend > 0, "Recovering",\n      Achievement >= 0.8, "At Risk",\n      "Critical"\n    )\n\n-- Dynamic measure driven by slicer\nSelected Metric = \n  VAR Choice = SELECTEDVALUE(MetricSlicer[Metric], "Sales")\n  RETURN\n    SWITCH(\n      Choice,\n      "Sales", [Total Sales],\n      "Profit", [Total Profit],\n      "Margin", [Profit Margin %],\n      "Orders", DISTINCTCOUNT(Sales[OrderID]),\n      [Total Sales]  -- default\n    )\n\n-- Formatted output\nSales Display = \n  VAR Value = [Total Sales]\n  RETURN\n    IF(Value >= 1000000,\n      FORMAT(Value / 1000000, "#,0.0") & "M",\n      FORMAT(Value / 1000, "#,0") & "K"\n    )',
    ['VAR used for repeated values','SWITCH replaces nested IF','Dynamic measure responds to slicer','Format adapts to magnitude'],'VAR is not just style — it computes once instead of every reference, which matters in complex measures.'),

  pbi(6,'dax','DAX Formulas & Calculations','Ranking & TopN Analysis',['Apply RANKX for dynamic ranking','Filter to Top N with TOPN','Create conditional ranking'],['Write RANKX to rank products by sales','Handle tie-breaking in ranks','Use TOPN to get top 5 products','Combine TOPN with CALCULATE','Create a "Top N + Other" pattern','Make N dynamic with a parameter','Test ranking in different visual contexts'],
    'RANKX evaluates in the current filter context. Use TOPN to filter a table to the top rows, not to display rank numbers.',
    'Product Rank = \n  RANKX(ALL(Products[Name]), [Total Sales], , DESC, Dense)',
    'Complete ranking solution with Top N + Other.',
    'Product Rank = \n  RANKX(\n    ALL(Products[Name]),\n    [Total Sales],\n    ,\n    DESC,\n    Dense  -- no gaps in rank\n  )\n\nTop 5 Sales = \n  CALCULATE(\n    [Total Sales],\n    TOPN(5, ALL(Products[Name]), [Total Sales], DESC)\n  )\n\nOther Sales = \n  [Total Sales] - [Top 5 Sales]\n\n-- Dynamic Top N (parameter table)\nTop N Sales = \n  VAR N = SELECTEDVALUE(TopN[Value], 5)\n  RETURN\n    CALCULATE(\n      [Total Sales],\n      TOPN(N, ALL(Products[Name]), [Total Sales], DESC)\n    )\n\nIs Top N = \n  VAR CurrentRank = [Product Rank]\n  VAR N = SELECTEDVALUE(TopN[Value], 5)\n  RETURN\n    IF(CurrentRank <= N, "Top " & N, "Other")',
    ['Rank is dense (no gaps)','Top 5 + Other sums to total','Dynamic N responds to parameter','Ranking updates with filters'],'RANKX ranks within ALL(column) — use ALL to rank against the full list regardless of visual filters.'),

  pbi(7,'dax','DAX Formulas & Calculations','Advanced Filter Functions',['Use FILTER, ALL, VALUES, ALLEXCEPT','Understand the filter propagation model','Build complex filter combinations'],['Compare ALL vs ALLEXCEPT vs ALLSELECTED','Use FILTER with complex conditions','Combine CALCULATE with FILTER for AND logic','Use KEEPFILTERS to AND with existing context','Create a virtual relationship with TREATAS','Test each pattern in a matrix visual','Document when to use each'],
    'ALL removes filters. ALLEXCEPT removes all except specified. ALLSELECTED respects slicer but ignores visual filter. KEEPFILTERS ANDs instead of replacing.',
    'Sales Big Orders = \n  CALCULATE(\n    [Total Sales],\n    FILTER(Sales, Sales[Amount] > 500)\n  )',
    'Advanced filter function library.',
    '-- ALL: removes all filters from table/column\nTotal Ignoring Filters = \n  CALCULATE([Total Sales], ALL(Sales))\n\n-- ALLEXCEPT: remove all except Region\nSales Keep Region = \n  CALCULATE([Total Sales], ALLEXCEPT(Sales, Sales[Region]))\n\n-- ALLSELECTED: respect slicer, ignore row context\nSales % of Visible = \n  DIVIDE(\n    [Total Sales],\n    CALCULATE([Total Sales], ALLSELECTED(Sales))\n  )\n\n-- FILTER: complex conditions\nPremium Sales = \n  CALCULATE(\n    [Total Sales],\n    FILTER(\n      ALL(Sales),\n      Sales[Amount] > 500 && Sales[Category] = "Premium"\n    )\n  )\n\n-- KEEPFILTERS: AND with existing context\nEast Premium = \n  CALCULATE(\n    [Total Sales],\n    KEEPFILTERS(Sales[Category] = "Premium")\n    -- Region filter from visual is preserved\n  )\n\n-- TREATAS: virtual relationship\nBudget for Actual Products = \n  CALCULATE(\n    SUM(Budget[Amount]),\n    TREATAS(VALUES(Sales[ProductID]), Budget[ProductID])\n  )',
    ['ALL removes all filters correctly','ALLSELECTED respects slicer','KEEPFILTERS ANDs not replaces','TREATAS bridges unrelated tables'],'Master ALL/ALLEXCEPT/ALLSELECTED — they control 90% of complex DAX patterns.'),

  pbi(8,'dax','DAX Formulas & Calculations','Semi-Additive Measures & Snapshots',['Handle balance/inventory data correctly','Use LASTDATE and LASTNONBLANK','Build semi-additive patterns'],['Understand why SUM fails for balances','Use LASTDATE to get month-end value','Use LASTNONBLANK for sparse data','Calculate average daily balance','Handle opening vs closing balances','Build a period-end snapshot measure','Test across different time granularities'],
    'Balance-type data is semi-additive: you can sum across accounts but not across time. Use LASTDATE or LASTNONBLANK instead of SUM.',
    'Closing Balance = \n  CALCULATE(\n    SUM(Balances[Amount]),\n    LASTDATE(Dates[Date])\n  )',
    'Complete semi-additive measure set.',
    'Closing Balance = \n  CALCULATE(\n    SUM(Balances[Amount]),\n    LASTDATE(Dates[Date])\n  )\n\nOpening Balance = \n  CALCULATE(\n    SUM(Balances[Amount]),\n    FIRSTDATE(Dates[Date])\n  )\n\nNet Change = [Closing Balance] - [Opening Balance]\n\n-- For sparse data (not every date has a value)\nLatest Balance = \n  CALCULATE(\n    SUM(Balances[Amount]),\n    LASTNONBLANK(Dates[Date], CALCULATE(COUNTROWS(Balances)))\n  )\n\n-- Average daily balance for interest calculation\nAvg Daily Balance = \n  AVERAGEX(\n    Dates,\n    CALCULATE(SUM(Balances[Amount]))\n  )\n\n-- Inventory at end of month\nMonth End Inventory = \n  CALCULATE(\n    SUM(Inventory[Qty]),\n    LASTDATE(Dates[Date])\n  )',
    ['Closing balance shows last day value','Opening balance shows first day','Net change = closing - opening','Works at month, quarter, and year'],'Semi-additive measures are the #1 gotcha for financial models — SUM gives nonsense for balance data.'),

  pbi(9,'dax','DAX Formulas & Calculations','Calculation Groups',['Create calculation groups for time intelligence','Apply calculation groups to any measure','Understand precedence rules'],['Create a calculation group named "Time Calculation"','Add items: Current, YTD, PY, YoY%','Define the expression for each item','Apply to Total Sales in a matrix','Verify it works with any base measure','Handle formatting per calculation item','Test with multiple measures'],
    'Calculation groups apply a DAX pattern to any measure dynamically. Create once, use everywhere — instead of writing YTD for every measure.',
    '-- In Tabular Editor:\n-- Calculation Group: Time Calculation\n-- Item: YTD\nTOTALYTD(SELECTEDMEASURE(), Dates[Date])',
    'Complete calculation group with time patterns.',
    '-- Created via Tabular Editor or TMDL\n-- Calculation Group: Time Calculation\n-- on column: Time Calculation[Selection]\n\n-- Item 1: Current Period\nSELECTEDMEASURE()\n\n-- Item 2: YTD\nTOTALYTD(SELECTEDMEASURE(), Dates[Date])\n\n-- Item 3: Prior Year\nCALCULATE(\n  SELECTEDMEASURE(),\n  SAMEPERIODLASTYEAR(Dates[Date])\n)\n\n-- Item 4: YoY %\nVAR Current = SELECTEDMEASURE()\nVAR Prior = CALCULATE(SELECTEDMEASURE(), SAMEPERIODLASTYEAR(Dates[Date]))\nRETURN\n  DIVIDE(Current - Prior, Prior)\n\n-- Item 5: Prior Month\nCALCULATE(\n  SELECTEDMEASURE(),\n  PARALLELPERIOD(Dates[Date], -1, MONTH)\n)\n\n-- FormatString for YoY %:\n-- \"0.0%;-0.0%;0.0%\"',
    ['Calculation group applies to any measure','YTD resets correctly','Prior year shows last year value','YoY format shows percentage'],'Calculation groups are the DRY principle for DAX — define time intelligence once, apply everywhere.'),

  pbi(10,'dax','DAX Formulas & Calculations','Performance Optimization',['Identify slow measures with DAX Studio','Optimize using variables and early filtering','Apply the VertiPaq analyzer'],['Install DAX Studio and connect to model','Run a slow measure and capture the query plan','Use Server Timings to find bottlenecks','Check Storage Engine vs Formula Engine time','Rewrite using VAR to reduce recalculation','Use REMOVEFILTERS instead of ALL where possible','Compare before/after execution times'],
    'Formula Engine (FE) is single-threaded and slow. Storage Engine (SE) is multi-threaded and fast. Push work to SE by simplifying expressions.',
    '-- Before (slow): nested CALCULATE\nSlow = CALCULATE(SUM(Sales[Amount]),\n  FILTER(ALL(Sales), Sales[Date] >= DATE(2025,1,1)))\n-- After (fast): simple filter\nFast = CALCULATE(SUM(Sales[Amount]),\n  Dates[Year] = 2025)',
    'Optimization patterns with performance comparison.',
    '-- Pattern 1: Use VAR to avoid recalculation\n-- BEFORE (evaluates [Total Sales] 3 times)\nBad = IF([Total Sales] > 1000,\n  [Total Sales] * 0.1, [Total Sales] * 0.05)\n-- AFTER (evaluates once)\nGood = \n  VAR Sales = [Total Sales]\n  RETURN IF(Sales > 1000, Sales * 0.1, Sales * 0.05)\n\n-- Pattern 2: Avoid FILTER(table) when possible\n-- BEFORE (iterates all rows)\nSlow = CALCULATE([Total Sales],\n  FILTER(Sales, Sales[Region] = "East"))\n-- AFTER (uses column filter → SE handles it)\nFast = CALCULATE([Total Sales], Sales[Region] = "East")\n\n-- Pattern 3: DISTINCTCOUNT vs SUMX\n-- BEFORE\nSlow = SUMX(VALUES(Sales[CustomerID]), 1)\n-- AFTER\nFast = DISTINCTCOUNT(Sales[CustomerID])\n\n-- Pattern 4: Reduce cardinality\n-- BEFORE: filtering a high-cardinality column\nSlow = CALCULATE([Total Sales],\n  FILTER(ALL(Sales[TransactionID]), LEFT(Sales[TransactionID],2) = "AB"))\n-- AFTER: add a computed column and filter that\nFast = CALCULATE([Total Sales], Sales[TxPrefix] = "AB")',
    ['Server Timings captured','FE vs SE time identified','Rewritten measure is faster','No FILTER(table) for simple conditions'],'90% of DAX performance issues come from unnecessary FILTER(table) calls — use direct column filters whenever possible.'),

  pbi(11,'dax','DAX Formulas & Calculations','Dynamic Format Strings',['Apply FORMAT for conditional display','Use calculation items for dynamic formatting','Build format strings that adapt to magnitude'],['Format currency with thousands separator','Format percentage with 1 decimal','Build a magnitude-aware format (K, M, B)','Use conditional formatting in measures','Apply format strings in calculation groups','Test across different locales','Handle negative numbers with color'],
    'FORMAT returns text — use sparingly. For display, use measure format strings or calculation group format properties.',
    'Sales Formatted = \n  VAR V = [Total Sales]\n  RETURN\n    IF(V >= 1E6, FORMAT(V/1E6, "#,0.0") & "M",\n    IF(V >= 1E3, FORMAT(V/1E3, "#,0") & "K",\n    FORMAT(V, "#,0")))',
    'Complete dynamic formatting system.',
    'Sales Display = \n  VAR V = [Total Sales]\n  RETURN\n    SWITCH(\n      TRUE(),\n      V >= 1E9, FORMAT(V / 1E9, "#,0.00") & "B",\n      V >= 1E6, FORMAT(V / 1E6, "#,0.0") & "M",\n      V >= 1E3, FORMAT(V / 1E3, "#,0") & "K",\n      FORMAT(V, "#,0")\n    )\n\n-- Conditional color (for card visuals)\nSales Color = \n  VAR V = [MoM Change %]\n  RETURN\n    SWITCH(\n      TRUE(),\n      V > 0.05, "#2a9d8f",   -- strong green\n      V > 0, "#56c596",       -- light green\n      V > -0.05, "#e9c46a",   -- yellow\n      "#e63946"               -- red\n    )\n\n-- Dynamic format string (for calculation groups)\n-- Applied as FormatString expression:\nVAR V = SELECTEDMEASURE()\nRETURN\n  IF(ABS(V) < 1, \"0.0%;-0.0%\",\n  IF(ABS(V) >= 1E6, \"$#,0.0,,M\",\n  \"$#,0\"))',
    ['Numbers show K/M/B appropriately','Percentages show 1 decimal','Colors indicate direction','Negative values formatted correctly'],'Good formatting makes dashboards scannable — the eye reads $2.4M faster than $2,400,000.'),

  // ── Report Design & Visualization (11 lessons) ────────────────────────
  pbi(1,'report-design','Report Design & Visualization','Layout Principles & Grid System',['Apply the F-pattern layout','Use consistent spacing with a 16px grid','Create visual hierarchy with size and position'],['Set page size to 16:9 (1280x720)','Enable gridlines and snap-to-grid','Place primary KPI cards in top row','Position trend chart in middle-left (largest area)','Add context filters (slicers) top-right','Place detail table at bottom','Verify 5-second readability test'],
    'F-pattern: users scan top-left first, then across, then down. Largest visual = most important data. Use consistent gutters (16px or 24px).',
    '-- Page Layout (1280x720 grid)\nTop Row:    [KPI 1] [KPI 2] [KPI 3] [Slicer Bar]\nMiddle:     [Main Chart (wide)]    [Secondary Chart]\nBottom:     [Detail Table (full width)]',
    'Complete page layout specification.',
    '-- Cortex Dashboard Layout Spec\n-- Canvas: 1280 x 720 (16:9)\n-- Grid: 16px\n-- Gutter: 16px between visuals\n\nHeader Bar (y:0, h:48):\n  Logo (x:16) | Title (x:80) | Date Range Slicer (x:800, w:464)\n\nKPI Row (y:64, h:96):\n  Revenue Card (x:16, w:296) | Margin Card (x:328, w:296)\n  Orders Card (x:640, w:296) | NPS Card (x:952, w:296)\n\nMain Area (y:176, h:320):\n  Revenue Trend Line (x:16, w:624, h:320)\n  Region Breakdown Bar (x:656, w:608, h:152)\n  Product Treemap (x:656, w:608, h:152, y:344)\n\nDetail Table (y:512, h:192):\n  Full-width table (x:16, w:1248)\n\n-- Rules:\n-- 1. All visuals align to 16px grid\n-- 2. Consistent border-radius: 8px\n-- 3. No visual titles > 14pt\n-- 4. Slicer always visible (no hidden filters)',
    ['All visuals aligned to grid','Primary metric top-left','Main insight visible in 5 seconds','Consistent gutters throughout'],'A grid-based layout is the foundation of professional dashboards — snap everything to 16px.'),

  pbi(2,'report-design','Report Design & Visualization','Chart Selection & Best Practices',['Match data to correct chart type','Apply Tufte principles','Avoid chartjunk'],['Identify data relationship: comparison, trend, part-of-whole','Select: bar for comparison, line for trend, treemap for hierarchy','Remove all 3D effects','Replace pie charts >5 slices with bar','Add direct labels instead of legends where possible','Maximize data-ink ratio','Test with colorblind simulation'],
    'Bar=comparison, Line=trend, Scatter=correlation, Treemap=hierarchy. Never use 3D. Never use pie with >5 slices.',
    '-- Chart Decision Tree:\n-- "How many categories?" → >5 → Bar Chart\n-- "Over time?" → Yes → Line Chart\n-- "Part of whole?" → Yes, <=5 parts → Donut\n-- "Correlation?" → Yes → Scatter\n-- "Hierarchy?" → Yes → Treemap',
    'Chart selection matrix with examples.',
    '-- Chart Selection Rules for Power BI:\n\n1. COMPARISON (between categories)\n   ✓ Bar chart (horizontal for long labels)\n   ✓ Clustered bar (2-3 series max)\n   ✗ Avoid: stacked bar >3 series\n\n2. TREND (over time)\n   ✓ Line chart (continuous data)\n   ✓ Area chart (show magnitude)\n   ✗ Avoid: bar chart for time series\n\n3. PART-OF-WHOLE\n   ✓ Donut (<=5 segments)\n   ✓ Treemap (hierarchical)\n   ✓ 100% stacked bar (comparing compositions)\n   ✗ Avoid: pie >5 segments\n\n4. DISTRIBUTION\n   ✓ Histogram\n   ✓ Box plot\n   ✗ Avoid: bar chart for continuous data\n\n5. RELATIONSHIP\n   ✓ Scatter plot\n   ✓ Bubble chart (3rd dimension)\n   ✗ Avoid: dual-axis charts (confusing)\n\n6. GEOGRAPHIC\n   ✓ Filled map (density)\n   ✓ Bubble map (magnitude)\n   ✗ Avoid: choropleth for absolute values',
    ['No pie charts >5 slices','No 3D effects','Direct labels where appropriate','Data-ink ratio > 0.7'],'The right chart makes the insight obvious — the wrong chart hides it.'),

  pbi(3,'report-design','Report Design & Visualization','Conditional Formatting & Visual Cues',['Apply background and font color rules','Use icon sets and data bars','Create KPI indicators'],['Apply background color scale to a matrix','Add data bars to a column','Set up icon sets (traffic lights)','Use field-based formatting with a measure','Apply conditional formatting to card visuals','Create a RAG status column','Test accessibility of color choices'],
    'Conditional formatting should guide attention, not decorate. Use sparingly — highlight exceptions, not everything.',
    '-- Field-based formatting measure:\nKPI Color = \n  SWITCH(TRUE(),\n    [Achievement] >= 1, "#2a9d8f",\n    [Achievement] >= 0.8, "#e9c46a",\n    "#e63946")',
    'Complete conditional formatting system.',
    '-- Measure for background color\nMargin BG Color = \n  VAR M = [Profit Margin %]\n  RETURN\n    SWITCH(TRUE(),\n      M >= 0.7, "#1a4731",   -- dark green bg\n      M >= 0.5, "#3d3200",   -- dark amber bg\n      "#4a1515"              -- dark red bg\n    )\n\n-- Measure for font color  \nMargin Font Color = \n  VAR M = [Profit Margin %]\n  RETURN\n    SWITCH(TRUE(),\n      M >= 0.7, "#56c596",\n      M >= 0.5, "#f6c98b",\n      "#ff6b6b"\n    )\n\n-- Icon logic (use in calculated column or measure)\nTrend Icon = \n  VAR Change = [MoM Change %]\n  RETURN\n    SWITCH(TRUE(),\n      Change > 0.05, UNICHAR(9650),     -- ▲\n      Change > -0.05, UNICHAR(9644),    -- ▬\n      UNICHAR(9660)                      -- ▼\n    )\n\n-- Data bar alternative (returns 0-1 for gauge)\nProgress Bar = \n  DIVIDE([Total Sales], [Sales Target], 0)',
    ['Background highlights exceptions only','Colors pass WCAG contrast','Icons supplement color (not replace)','KPI cards show status at a glance'],'Conditional formatting should highlight what needs attention — not paint everything in color.'),

  pbi(4,'report-design','Report Design & Visualization','Bookmarks, Buttons & Navigation',['Create interactive page navigation','Use bookmarks for toggle views','Build a report app experience'],['Add navigation buttons with icons','Create bookmarks for different views','Set up a toggle between chart and table','Add a reset-all-filters button','Create drill-through navigation','Set up tooltip pages','Test keyboard navigation'],
    'Bookmarks capture filter state + visual visibility. Use Selection Pane to toggle visual layers. Page navigation buttons make reports feel like apps.',
    '-- Bookmark pattern:\n-- 1. Create "Chart View" bookmark (chart visible, table hidden)\n-- 2. Create "Table View" bookmark (table visible, chart hidden)\n-- 3. Add button → Action → Bookmark → "Chart View"\n-- 4. Add button → Action → Bookmark → "Table View"',
    'Complete navigation system.',
    '-- Navigation Architecture:\n\n1. PAGE NAVIGATION\n   - Home button on every page → navigates to Overview\n   - Tab buttons: Overview | Sales | Products | Regions\n   - Each button: Action → Page Navigation → [target]\n\n2. VIEW TOGGLE (Bookmarks)\n   - Bookmark "Sales Chart View":\n     Selection: BarChart=Visible, DataTable=Hidden\n   - Bookmark "Sales Table View":\n     Selection: BarChart=Hidden, DataTable=Visible\n   - Toggle button switches between bookmarks\n   - Disable "Data" in bookmark (preserve filters)\n\n3. DRILL-THROUGH\n   - Detail page with drill-through field = ProductID\n   - Back button auto-created\n   - Passes all filter context\n\n4. TOOLTIPS\n   - Tooltip page (size: 320x240)\n   - Shows mini-chart + KPIs on hover\n   - Assigned via visual → Tooltip → Report Page\n\n5. RESET BUTTON\n   - Bookmark "Reset" captures default slicer state\n   - Button action → Bookmark → Reset\n   - Enable "Data" in this bookmark',
    ['Page navigation works on all pages','Toggle switches chart/table','Drill-through passes context','Reset clears all filters'],'Bookmarks + buttons turn static reports into interactive applications.'),

  pbi(5,'report-design','Report Design & Visualization','Mobile Layout & Responsive Design',['Create mobile-optimized views','Prioritize content for small screens','Test on actual devices'],['Open Mobile Layout view','Drag only essential visuals to mobile canvas','Stack KPIs vertically (1 column)','Place main chart below KPIs','Remove detail tables (link to full report)','Set touch-friendly slicer sizes','Test on phone and tablet'],
    'Mobile layout is a separate canvas — only include what fits. Users scroll vertically, not horizontally. Make touch targets at least 44px.',
    '-- Mobile Layout (Portrait 375x667):\nKPI Card 1 (full width)\nKPI Card 2 (full width)\nMain Chart (full width, tall)\nSlicer (dropdown, full width)\n-- No tables, no multi-select slicers',
    'Mobile layout specification.',
    '-- Mobile Layout Best Practices:\n\n1. CONTENT PRIORITY\n   - Show: Top 3 KPIs, 1 main chart, 1 slicer\n   - Hide: Tables, secondary charts, detailed slicers\n   - Link: "View full report" button at bottom\n\n2. LAYOUT RULES\n   - Single column stack (no side-by-side)\n   - KPI cards: full width, 80px height\n   - Chart: full width, 280px minimum height\n   - Slicer: dropdown mode (saves space)\n   - Touch targets: minimum 44px\n\n3. VISUAL ADJUSTMENTS\n   - Larger font sizes (+2pt minimum)\n   - Remove axis labels that truncate\n   - Use horizontal bar charts (vertical space)\n   - Simplify legends or remove\n\n4. TESTING\n   - Power BI mobile app on iOS/Android\n   - Check both portrait and landscape\n   - Test all interactions (drill, filter)\n   - Verify load time < 5 seconds on 4G',
    ['Mobile layout created','KPIs visible without scrolling','Chart readable on phone','Touch targets >= 44px'],'Design mobile-first — if it works on a phone, it works everywhere.'),

  pbi(6,'report-design','Report Design & Visualization','Accessibility & WCAG Compliance',['Meet WCAG 2.1 AA standards','Add alt text to all visuals','Ensure keyboard navigation'],['Add alt text to every visual','Check color contrast (4.5:1 minimum)','Ensure no information is color-only','Test tab order in report','Add data table alternatives for charts','Use markers + color for line charts','Run Accessibility Checker'],
    'Alt text describes the visual purpose and key insight. Tab order should follow reading order. Never use color alone to convey meaning.',
    '-- Alt text pattern:\n-- "[Chart type] showing [what] by [dimension].\n--  Key insight: [main takeaway]"\n-- Example: "Bar chart showing revenue by region.\n--  Key insight: West region leads at $2.4M."',
    'Accessibility checklist implementation.',
    '-- Accessibility Checklist for Power BI:\n\n1. ALT TEXT (every visual)\n   Format: "[Type] showing [metric] by [dimension]. [Insight]."\n   Example: "Line chart showing monthly revenue trend.\n   Revenue grew 15% from Jan to Dec 2025."\n   - Static alt text: always visible\n   - Dynamic: use measure in alt text field\n\n2. COLOR CONTRAST\n   - Text on background: >= 4.5:1 (AA)\n   - Large text (18pt+): >= 3:1\n   - Tool: WebAIM Contrast Checker\n   - Test both light and dark themes\n\n3. NON-COLOR INDICATORS\n   - Add shapes/markers to line charts\n   - Use patterns or labels with color\n   - Icons + color for status (not color alone)\n\n4. KEYBOARD NAVIGATION\n   - Tab order matches visual reading order\n   - All interactive elements reachable\n   - Focus indicator visible\n   - Test: Tab, Enter, Arrow keys, Escape\n\n5. SCREEN READER\n   - Test with Narrator (Windows)\n   - Visual titles are descriptive\n   - Avoid abbreviations in labels\n\n6. DATA TABLES\n   - Show Data Table option enabled\n   - Or: include table visual as alternative',
    ['All visuals have alt text','Color contrast >= 4.5:1','No color-only indicators','Tab order is logical'],'Accessibility is not optional — it is a legal requirement and a quality signal.'),

  pbi(7,'report-design','Report Design & Visualization','Custom Themes & Branding',['Create a custom JSON theme','Apply brand colors consistently','Use theme-level defaults'],['Export current theme as JSON','Modify colors to match brand palette','Set default fonts and sizes','Configure data colors for consistency','Apply conditional formatting defaults','Import and apply the theme','Distribute theme file to team'],
    'A JSON theme controls 95% of visual formatting in one file. Start from an exported theme, then customize.',
    '{\n  "name": "Corporate",\n  "dataColors": ["#1a56db", "#2a9d8f", "#e9c46a"],\n  "background": { "color": "#0b1d2a" },\n  "foreground": { "color": "#f8f9fb" }\n}',
    'Complete Power BI theme file.',
    '{\n  "name": "Cortex Dashboard Theme",\n  "dataColors": [\n    "#7C6BF0", "#4ECDC4", "#FF6B6B",\n    "#FFB347", "#54A0FF", "#56C596",\n    "#F2C811", "#E876C4"\n  ],\n  "background": { "color": "#091722" },\n  "foreground": { "color": "#f8f9fb" },\n  "tableAccent": "#7C6BF0",\n  "textClasses": {\n    "title": {\n      "fontFace": "Segoe UI Semibold",\n      "fontSize": "14px",\n      "color": "#f8f9fb"\n    },\n    "header": {\n      "fontFace": "Segoe UI",\n      "fontSize": "11px",\n      "color": "#d5dbe6"\n    },\n    "label": {\n      "fontFace": "Segoe UI",\n      "fontSize": "10px",\n      "color": "#7a8ea0"\n    }\n  },\n  "visualStyles": {\n    "*": {\n      "*": {\n        "border": [{ "show": false }],\n        "background": [{ "color": "#142a3b", "transparency": 10 }],\n        "title": [{ "fontColor": "#f8f9fb" }]\n      }\n    }\n  }\n}',
    ['Theme applies to all pages','Brand colors consistent','Fonts match style guide','Dark/light variants available'],'A custom theme is your brand in code — define it once and every new visual inherits it.'),

  pbi(8,'report-design','Report Design & Visualization','Storytelling with Data',['Structure a data narrative','Guide the viewer through insights','Use annotations and focus'],['Identify the story: what changed, why, what to do','Structure: context → insight → recommendation','Add annotations to highlight key data points','Use bookmarks for guided walkthrough','Create a summary page with key messages','Add commentary text boxes','Practice presenting the report in 2 minutes'],
    'Every report answers three questions: What happened? Why? What should we do? Structure your pages to answer them in order.',
    '-- Story Structure:\n-- Page 1: Executive Summary (the answer)\n-- Page 2: The Evidence (charts + trends)\n-- Page 3: Deep Dive (detail for exploration)\n-- Page 4: Recommendations (next steps)',
    'Report storytelling framework.',
    '-- Data Storytelling Framework for Power BI:\n\n1. EXECUTIVE SUMMARY (Page 1)\n   - 3-4 KPI cards with RAG status\n   - One sentence: "Revenue grew 12% YTD, driven by East region"\n   - Navigation buttons to detail pages\n   - No interaction needed — scannable in 10 seconds\n\n2. TREND & CONTEXT (Page 2)\n   - Main trend line with annotations at key events\n   - "Revenue dipped in March due to supply chain delay"\n   - Comparison to prior year / target\n   - Bookmarked views: by Region, by Product, by Channel\n\n3. DEEP DIVE (Page 3)\n   - Matrix with drill-through to detail\n   - Scatter plot for outlier analysis\n   - Slicers for exploration\n   - This page is for analysts, not executives\n\n4. RECOMMENDATIONS (Page 4)\n   - Text boxes with numbered actions\n   - Supporting data for each recommendation\n   - Owner and deadline columns\n   - "If we increase East marketing 20%, model shows +$400K"\n\n-- Annotation Pattern:\n-- Use text boxes anchored to data points\n-- Format: "[Date]: [Event] → [Impact]"\n-- Example: "Mar 15: Supplier delay → -8% revenue"',
    ['Story follows context→insight→action','Annotations highlight key events','Summary page answers main question','2-minute presentation works'],'Data without narrative is just noise — every chart should answer a question.'),

  pbi(9,'report-design','Report Design & Visualization','Performance Optimization for Reports',['Reduce visual render time','Optimize query reduction','Apply best practices for large datasets'],['Enable Performance Analyzer','Identify slowest visuals','Reduce visual count per page (<15)','Collapse slicer interactions','Enable query reduction settings','Replace complex visuals with simpler ones','Compare before/after render times'],
    'Rule of thumb: <15 visuals per page. Each visual fires a DAX query — fewer visuals = faster load. Use query reduction to batch filter changes.',
    '-- Performance Analyzer output:\nVisual: Region Bar Chart\n  DAX Query: 450ms\n  Visual Render: 120ms\n  Other: 30ms\n  Total: 600ms\n-- Target: <1000ms per visual',
    'Report performance optimization guide.',
    '-- Performance Optimization Checklist:\n\n1. VISUAL COUNT (biggest impact)\n   - Maximum 15 visuals per page\n   - Move secondary visuals to drill-through\n   - Use bookmarks for alternate views (not more visuals)\n   - Remove decorative elements\n\n2. QUERY REDUCTION\n   - File → Options → Query Reduction\n   - Enable "Add apply button to slicers"\n   - Enable "Add apply button to filters"\n   - Reduces queries during slicer interaction\n\n3. SLOW VISUAL FIXES\n   - Replace high-cardinality tables with Top N\n   - Remove unnecessary columns from tables\n   - Use aggregations for large datasets\n   - Replace custom visuals with built-in\n\n4. DATA MODEL\n   - Remove unused columns\n   - Set column as "Hidden" not deleted\n   - Use Import mode (not DirectQuery) if <1GB\n   - Create aggregation tables for summary views\n\n5. MEASURE OPTIMIZATION\n   - Check with DAX Studio\n   - Use VAR to avoid recalculation\n   - Remove FORMAT() from non-card visuals\n   - Avoid iterators on large tables',
    ['Render time < 5 seconds total','Each visual < 1 second','Query count reduced','Performance Analyzer shows improvement'],'A fast report gets used. A slow report gets abandoned.'),

  pbi(10,'report-design','Report Design & Visualization','Custom Visuals & Deneb/Vega-Lite',['Use Deneb for custom Vega-Lite visuals','Create visualizations not possible with built-in visuals','Integrate custom visuals safely'],['Install Deneb from AppSource','Create a basic bar chart in Vega-Lite syntax','Build a lollipop chart (not available built-in)','Add conditional color encoding','Create a bullet chart for KPI vs target','Test interactivity and cross-filtering','Document when to use custom vs built-in'],
    'Deneb brings Vega-Lite to Power BI — create any visualization with a declarative JSON spec. Use for charts Power BI doesn\'t offer natively.',
    '{\n  "mark": "bar",\n  "encoding": {\n    "x": {"field": "Sales", "type": "quantitative"},\n    "y": {"field": "Product", "type": "nominal", "sort": "-x"}\n  }\n}',
    'Lollipop chart with conditional color in Deneb.',
    '{\n  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",\n  "layer": [\n    {\n      "mark": {"type": "rule", "strokeWidth": 2},\n      "encoding": {\n        "x": {"field": "Sales", "type": "quantitative"},\n        "y": {"field": "Product", "type": "nominal",\n          "sort": {"field": "Sales", "order": "descending"}},\n        "color": {\n          "condition": {\n            "test": "datum.Sales >= datum.Target",\n            "value": "#2a9d8f"\n          },\n          "value": "#e63946"\n        }\n      }\n    },\n    {\n      "mark": {"type": "circle", "size": 120},\n      "encoding": {\n        "x": {"field": "Sales", "type": "quantitative"},\n        "y": {"field": "Product", "type": "nominal",\n          "sort": {"field": "Sales", "order": "descending"}},\n        "color": {\n          "condition": {\n            "test": "datum.Sales >= datum.Target",\n            "value": "#2a9d8f"\n          },\n          "value": "#e63946"\n        }\n      }\n    },\n    {\n      "mark": {"type": "tick", "thickness": 3, "color": "#f8f9fb"},\n      "encoding": {\n        "x": {"field": "Target", "type": "quantitative"},\n        "y": {"field": "Product", "type": "nominal",\n          "sort": {"field": "Sales", "order": "descending"}}\n      }\n    }\n  ]\n}',
    ['Lollipop chart renders correctly','Colors indicate above/below target','Target marker visible','Cross-filtering works'],'Deneb fills the gap between built-in visuals and full custom development — learn Vega-Lite for maximum flexibility.'),

  pbi(11,'report-design','Report Design & Visualization','Report Deployment & Version Control',['Publish reports to Power BI Service','Set up deployment pipelines','Manage report versions'],['Publish from Desktop to a workspace','Configure scheduled refresh','Set up Development → Test → Production pipeline','Use deployment rules for connection strings','Create a release checklist','Set up workspace roles (Admin/Member/Contributor/Viewer)','Document deployment process'],
    'Deployment pipelines give you Dev → Test → Prod stages. Deployment rules let you swap connection strings per stage without editing the report.',
    '-- Deployment Pipeline:\n-- [Development] → Compare → [Test] → Compare → [Production]\n-- Deployment Rules: change SQL server per stage\n-- Dev: dev-sql.company.com\n-- Prod: prod-sql.company.com',
    'Complete deployment workflow.',
    '-- Power BI Deployment Pipeline Setup:\n\n1. CREATE PIPELINE\n   - Deployment Pipelines → Create\n   - Name: "Sales Reports Pipeline"\n   - Assign workspaces: Dev, Test, Prod\n\n2. DEPLOYMENT RULES\n   - For each dataset in Test/Prod:\n   - Data source rules:\n     Dev:  server=dev-sql.co, db=SalesDev\n     Test: server=test-sql.co, db=SalesTest\n     Prod: server=prod-sql.co, db=SalesProd\n   - Parameter rules: update any Power Query parameters\n\n3. DEPLOYMENT PROCESS\n   a. Develop in Desktop → Publish to Dev workspace\n   b. Test in Dev workspace\n   c. Deploy Dev → Test (compare changes first)\n   d. UAT in Test workspace\n   e. Deploy Test → Prod (with approval)\n   f. Verify Prod refresh works\n\n4. WORKSPACE SECURITY\n   - Admin: IT / BI Team Lead\n   - Member: Report developers\n   - Contributor: Data analysts\n   - Viewer: Business users\n\n5. RELEASE CHECKLIST\n   [ ] All measures verified\n   [ ] Refresh tested with prod credentials\n   [ ] RLS tested per role\n   [ ] Mobile layout verified\n   [ ] Accessibility check passed\n   [ ] Stakeholder sign-off',
    ['Pipeline has 3 stages','Deployment rules swap connections','Workspace roles configured','Release checklist complete'],'Deployment pipelines are CI/CD for Power BI — never publish directly to production.'),

  // ── Data Modeling & Relationships (11 lessons) ────────────────────────
  pbi(1,'data-modeling','Data Modeling & Relationships','Star Schema Fundamentals',['Understand fact vs dimension tables','Design a star schema','Apply naming conventions'],['Identify the grain of your fact table','List dimension tables needed','Draw the star schema diagram','Ensure 1-to-many relationships','Name facts as Fact_[process] and dims as Dim_[entity]','Verify no many-to-many relationships','Document the schema'],
    'Star schema: one fact table (events/transactions) surrounded by dimension tables (descriptive attributes). Facts have foreign keys pointing to dimension primary keys.',
    '-- Star Schema:\n-- Fact_Sales (OrderID, DateKey, ProductKey, Amount)\n--   → Dim_Date (DateKey, Year, Month, Quarter)\n--   → Dim_Product (ProductKey, Name, Category)\n--   → Dim_Customer (CustomerKey, Name, Region)',
    'Complete star schema design.',
    '-- Cortex Learning Star Schema:\n\nFact_Sales:\n  SalesKey (PK, surrogate)\n  DateKey (FK → Dim_Date)\n  ProductKey (FK → Dim_Product)\n  CustomerKey (FK → Dim_Customer)\n  StoreKey (FK → Dim_Store)\n  Quantity (measure)\n  UnitPrice (measure)\n  Discount (measure)\n  TotalAmount (measure)\n  COGS (measure)\n\nDim_Date:\n  DateKey (PK)\n  Date, Year, Quarter, Month, MonthName\n  FiscalYear, FiscalQuarter\n  IsWeekend, IsHoliday\n\nDim_Product:\n  ProductKey (PK)\n  ProductName, Category, SubCategory\n  Brand, UnitCost, ListPrice\n  IsActive\n\nDim_Customer:\n  CustomerKey (PK)\n  CustomerName, Segment, Industry\n  City, State, Region, Country\n  AccountManager\n\nDim_Store:\n  StoreKey (PK)\n  StoreName, StoreType\n  City, State, Region\n  OpenDate, SquareFootage\n\n-- Rules:\n-- 1. Fact table at lowest grain (one row per transaction)\n-- 2. All relationships are 1-to-many (dim → fact)\n-- 3. No direct dim-to-dim relationships\n-- 4. Surrogate keys (integers) for joins\n-- 5. Date table is always a dimension',
    ['Fact table identified at correct grain','All dimensions connected 1-to-many','No many-to-many relationships','Naming convention followed'],'Star schema is the only modeling pattern optimized for Power BI — VertiPaq compresses it best.'),

  pbi(2,'data-modeling','Data Modeling & Relationships','Relationship Types & Cross-Filter Direction',['Configure 1:1, 1:many, many:many relationships','Set cross-filter direction','Resolve ambiguous relationships'],['Create 1-to-many relationship (drag and drop)','Set cross-filter to Single (default)','Test: filter flows dim → fact only','Enable Bi-directional on one relationship','Observe the performance impact','Create a many-to-many via bridge table','Deactivate an ambiguous relationship'],
    'Default: Single direction (dim filters fact). Bi-directional lets fact filter dim — use sparingly as it creates ambiguity and slows queries.',
    '-- Relationship: Dim_Product → Fact_Sales\n-- Cardinality: 1:Many\n-- Cross-filter: Single (Product filters Sales)\n-- \n-- To make Sales filter Products:\n-- Either: Set to Both (bi-directional)\n-- Or: Use CROSSFILTER() in DAX (better)',
    'Relationship management patterns.',
    '-- Relationship Best Practices:\n\n1. DEFAULT: Single direction\n   Dim_Date ──1:*──> Fact_Sales (Single)\n   Dim_Product ──1:*──> Fact_Sales (Single)\n   Filter flows: Dim → Fact only\n\n2. BI-DIRECTIONAL (use sparingly)\n   Dim_Product ──1:*──> Fact_Sales (Both)\n   Use case: Show products WITH sales in a slicer\n   Impact: Slower queries, possible ambiguity\n   Better: Use CROSSFILTER() in specific measures\n\n3. MANY-TO-MANY (via bridge table)\n   Fact_Sales ──*:1──> Bridge_ProductCustomer ──1:*──> Dim_Customer\n   Or use TREATAS() for virtual relationships\n\n4. ROLE-PLAYING DIMENSIONS\n   Dim_Date connects to multiple date columns:\n   - Fact_Sales[OrderDate] → Active relationship\n   - Fact_Sales[ShipDate] → Inactive relationship\n   Use USERELATIONSHIP() in measures:\n   Shipped Sales = CALCULATE([Total Sales],\n     USERELATIONSHIP(Fact_Sales[ShipDate], Dim_Date[Date]))\n\n5. AMBIGUITY RESOLUTION\n   - Only ONE active path between any two tables\n   - Deactivate secondary paths\n   - Use USERELATIONSHIP() to activate when needed',
    ['All relationships are 1:many where possible','No unnecessary bi-directional','Inactive relationships documented','USERELATIONSHIP used for role-playing dims'],'Single-direction relationships are faster and less ambiguous — only use bi-directional when you have a specific need.'),

  pbi(3,'data-modeling','Data Modeling & Relationships','Row-Level Security (RLS)',['Design RLS roles','Apply DAX filter expressions','Test security with different users'],['Create a role: "Regional Manager"','Add DAX filter: [Region] = USERPRINCIPALNAME()','Create a mapping table: User → Region','Join mapping table to fact via dimension','Test with "View as Role"','Combine static and dynamic RLS','Document security model'],
    'RLS filters data at the row level per user. Static RLS uses hardcoded values. Dynamic RLS uses a mapping table with USERPRINCIPALNAME().',
    '-- Static RLS:\n-- Role: East Region\n-- DAX Filter on Dim_Store: [Region] = "East"\n\n-- Dynamic RLS:\n-- DAX Filter on Security table:\n-- [UserEmail] = USERPRINCIPALNAME()',
    'Complete RLS implementation.',
    '-- Dynamic Row-Level Security:\n\n1. SECURITY TABLE\n   Security_UserRegion:\n   | UserEmail              | Region |\n   | east.mgr@company.com   | East   |\n   | west.mgr@company.com   | West   |\n   | ceo@company.com        | ALL    |\n\n2. RELATIONSHIPS\n   Security_UserRegion[Region] → Dim_Store[Region]\n   (1:Many, Single direction, Apply to Both)\n\n3. ROLE DEFINITION\n   Role: "Regional Access"\n   DAX Filter on Security_UserRegion:\n   [UserEmail] = USERPRINCIPALNAME()\n   || [Region] = "ALL"\n\n4. HOW IT WORKS\n   - User logs in → USERPRINCIPALNAME() returns email\n   - Filter on Security table → only matching rows\n   - Filter propagates: Security → Dim_Store → Fact_Sales\n   - User sees only their region\'s data\n   - CEO sees all (Region = "ALL" matches everything)\n\n5. TESTING\n   - Modeling → View as → Select role + user\n   - Verify: East manager sees only East data\n   - Verify: CEO sees all regions\n   - Test: measures respect RLS filters\n   - Publish and test in Service with actual users',
    ['RLS role created and tested','Dynamic filter uses USERPRINCIPALNAME','Manager sees only their region','Admin/CEO sees all data'],'RLS is security, not convenience — always test with real user accounts before going live.'),

  pbi(4,'data-modeling','Data Modeling & Relationships','Composite Models & DirectQuery',['Understand Import vs DirectQuery vs Dual','Create a composite model','Apply aggregations for performance'],['Import dimension tables','Set large fact table to DirectQuery','Create an aggregation table (Import mode)','Configure aggregation mappings','Test: aggregation hit vs DirectQuery fallback','Monitor query performance','Document the hybrid architecture'],
    'Composite models mix Import and DirectQuery. Import small dims for speed, DirectQuery large facts for freshness. Aggregations cache common queries.',
    '-- Composite Model:\n-- Dim_Date: Import (small, fast)\n-- Dim_Product: Import (small, fast)\n-- Fact_Sales: DirectQuery (large, real-time)\n-- Agg_Sales_Monthly: Import (pre-aggregated)',
    'Composite model with aggregation layer.',
    '-- Composite Model Architecture:\n\n1. IMPORT TABLES (cached, fast)\n   Dim_Date (3KB) → Import\n   Dim_Product (50KB) → Import\n   Dim_Customer (200KB) → Import\n   Dim_Store (5KB) → Import\n   Agg_SalesMonthly (1MB) → Import\n\n2. DIRECTQUERY TABLES (live, large)\n   Fact_Sales (500M rows) → DirectQuery\n\n3. AGGREGATION TABLE\n   Agg_SalesMonthly:\n   - DateMonth (from Fact_Sales.DateKey → month)\n   - ProductKey (GroupBy)\n   - StoreKey (GroupBy)\n   - SumAmount (SUM of Fact_Sales.Amount)\n   - CountOrders (COUNT of Fact_Sales.OrderID)\n\n4. AGGREGATION MAPPINGS\n   Table: Agg_SalesMonthly → Fact_Sales\n   SumAmount: SUM(Fact_Sales[Amount])\n   CountOrders: COUNT(Fact_Sales[OrderID])\n   ProductKey: GroupBy\n   StoreKey: GroupBy\n   Precedence: Agg_SalesMonthly = 1 (try first)\n\n5. BEHAVIOR\n   Query at monthly level → hits aggregation (fast)\n   Query at daily level → falls back to DirectQuery\n   All transparent to report consumer',
    ['Dims are Import mode','Fact is DirectQuery','Aggregation table created','Monthly queries hit cache'],'Composite models give you the best of both worlds — cached speed for common queries, live data for drill-down.'),

  pbi(5,'data-modeling','Data Modeling & Relationships','Model Optimization & VertiPaq',['Reduce model size using VertiPaq best practices','Remove unused columns','Optimize data types and cardinality'],['Open VertiPaq Analyzer in DAX Studio','Identify largest tables and columns','Remove high-cardinality text columns','Replace GUID keys with integers','Disable Auto Date/Time tables','Split large columns','Compare model size before and after'],
    'VertiPaq compresses by column — low cardinality columns compress dramatically. Remove GUIDs, long text, and unused columns.',
    '-- VertiPaq Analyzer shows:\n-- Column: Description (5M unique values) = 120MB\n-- Column: ProductKey (500 unique) = 0.2MB\n-- Action: Remove Description, keep ProductKey',
    'Model optimization checklist.',
    '-- VertiPaq Optimization Checklist:\n\n1. REMOVE UNUSED COLUMNS\n   - If not used in visuals, measures, or relationships\n   - Remove in Power Query (not just hide)\n   - Common offenders: audit columns, internal IDs\n\n2. REDUCE CARDINALITY\n   - Replace GUIDs with integer surrogate keys\n   - Truncate timestamps to date (if time not needed)\n   - Bin continuous values (age → age group)\n   - Remove decimal precision (2 decimals, not 10)\n\n3. OPTIMIZE DATA TYPES\n   - Use Int64 instead of Decimal where possible\n   - Whole Number for IDs and counts\n   - Fixed Decimal for currency\n   - Avoid Text for things that could be numbers\n\n4. DISABLE AUTO DATE/TIME\n   - File → Options → Data Load\n   - Uncheck "Auto date/time"\n   - Create your own Date table instead\n   - Saves ~8KB per date column\n\n5. SPLIT LARGE TABLES\n   - Separate high-cardinality columns\n   - Fact table: only keys + measures\n   - Move descriptive columns to dimensions\n\n6. MEASURE TABLE\n   - Create a blank table for measures\n   - Organize into display folders\n   - Keeps model clean and navigable',
    ['Model size reduced by >20%','No unused columns remain','Auto date/time disabled','GUIDs replaced with integers'],'Every MB of model size costs refresh time, memory, and money — optimize ruthlessly.'),

  pbi(6,'data-modeling','Data Modeling & Relationships','Slowly Changing Dimensions',['Implement Type 1 and Type 2 SCDs','Track historical changes','Build "as-of" reporting'],['Identify which dimensions change over time','Implement Type 1 (overwrite) for non-critical changes','Implement Type 2 (history rows) for critical changes','Add effective dates and current flags','Create measures that respect SCD Type 2','Handle the "current view" vs "historical view"','Test with a dimension change scenario'],
    'Type 1 overwrites (loses history). Type 2 adds rows with date ranges (preserves history). Use Type 2 for anything you need to report historically.',
    '-- SCD Type 2: Customer Region changed\n-- Before: CustomerKey=101, Region=East, Current=Y\n-- After:  CustomerKey=101, Region=East, Current=N, EndDate=2025-06\n--         CustomerKey=102(surrogate), Region=West, Current=Y, StartDate=2025-07',
    'SCD Type 2 implementation pattern.',
    '-- SCD Type 2 Dimension Design:\n\nDim_Customer_SCD2:\n  CustomerSK (Surrogate Key - auto increment)\n  CustomerBK (Business Key - original ID)\n  CustomerName\n  Segment\n  Region\n  AccountManager\n  EffectiveDate (when this version started)\n  ExpiryDate (when this version ended, 9999-12-31 if current)\n  IsCurrent (boolean flag)\n\n-- Example rows:\n-- SK=1001, BK=C-100, Region=East, Eff=2024-01-01, Exp=2025-06-30, Current=N\n-- SK=1002, BK=C-100, Region=West, Eff=2025-07-01, Exp=9999-12-31, Current=Y\n\n-- Fact table references: Fact_Sales.CustomerSK → Dim_Customer_SCD2.CustomerSK\n-- Each sale links to the customer version active at that time\n\n-- Current View measure:\nCurrent Customers = \n  CALCULATE(\n    DISTINCTCOUNT(Dim_Customer[CustomerBK]),\n    Dim_Customer[IsCurrent] = TRUE\n  )\n\n-- Historical View (sales attributed to region at time of sale):\n-- No special DAX needed — the fact table already points to\n-- the correct dimension row via surrogate key\n\n-- ETL Pattern (pseudo-code):\n-- 1. Match incoming record on BusinessKey\n-- 2. If attributes changed:\n--    a. Set existing row: ExpiryDate=yesterday, IsCurrent=N\n--    b. Insert new row: EffectiveDate=today, IsCurrent=Y\n-- 3. If no change: skip (or update Type 1 attributes)',
    ['Type 2 tracks history with date ranges','Current flag identifies active version','Fact table uses surrogate keys','Historical queries show past state'],'SCD Type 2 is how enterprises track truth over time — without it, you cannot explain what changed.'),

  pbi(7,'data-modeling','Data Modeling & Relationships','Many-to-Many Relationships',['Resolve M:M with bridge tables','Use TREATAS for virtual M:M','Understand bidirectional implications'],['Identify M:M scenario (e.g. students↔courses)','Create a bridge/junction table','Configure relationships through the bridge','Test filter propagation','Alternative: use TREATAS for virtual relationship','Compare performance of bridge vs TREATAS','Document which approach and why'],
    'True M:M requires a bridge table or TREATAS. Direct M:M relationships in Power BI exist but have limitations and performance issues.',
    '-- Bridge Table Pattern:\n-- Dim_Student ←1:*→ Bridge_Enrollment ←*:1→ Dim_Course\n-- Bridge has: StudentKey, CourseKey, EnrollDate',
    'Many-to-many resolution patterns.',
    '-- Pattern 1: Bridge Table (recommended)\nDim_Student ──1:*──> Bridge_Enrollment ──*:1──> Dim_Course\n\nBridge_Enrollment:\n  StudentKey (FK)\n  CourseKey (FK)\n  EnrollmentDate\n  Grade\n\n-- Measures work naturally:\nStudent Count = DISTINCTCOUNT(Bridge[StudentKey])\nCourse Count = DISTINCTCOUNT(Bridge[CourseKey])\nAvg Grade = AVERAGE(Bridge[Grade])\n\n-- Pattern 2: TREATAS (no bridge needed)\nSales by Budget Category = \n  CALCULATE(\n    [Total Sales],\n    TREATAS(\n      VALUES(Budget[Category]),\n      Sales[Category]\n    )\n  )\n-- TREATAS creates a virtual relationship at query time\n-- No physical table needed, but slower for large datasets\n\n-- Pattern 3: Direct M:M (Power BI native)\n-- Modeling → Relationship → Many-to-Many\n-- Limitations:\n-- - Requires bi-directional filtering\n-- - Can produce unexpected results with complex DAX\n-- - Performance overhead\n-- Use only when bridge table is impractical',
    ['M:M resolved without ambiguity','Bridge table connects both dims','Measures return correct counts','No unexpected cross-filtering'],'Bridge tables are the safest M:M pattern — they make the relationship explicit and debuggable.'),

  pbi(8,'data-modeling','Data Modeling & Relationships','Calculation Groups Deep Dive',['Create multi-purpose calculation groups','Handle format strings dynamically','Layer multiple calculation groups'],['Create "Time Intelligence" calculation group','Create "Currency Conversion" calculation group','Apply both simultaneously','Set precedence between groups','Define dynamic format strings per item','Test with various base measures','Handle edge cases (blank, division by zero)'],
    'Multiple calculation groups can combine. Precedence (lower number = applied first) determines order of operations.',
    '-- Tabular Editor → Model → New Calculation Group\n-- Name: "Time Calc"\n-- Column: "Period"\n-- Items: Current, YTD, PY, YoY%\n-- Each item uses SELECTEDMEASURE()',
    'Multi-layer calculation group system.',
    '-- Calculation Group 1: Time Intelligence (Precedence: 10)\nCurrent:\n  SELECTEDMEASURE()\n\nYTD:\n  TOTALYTD(SELECTEDMEASURE(), Dates[Date])\n\nPrior Year:\n  CALCULATE(SELECTEDMEASURE(), SAMEPERIODLASTYEAR(Dates[Date]))\n\nYoY Change:\n  VAR Curr = SELECTEDMEASURE()\n  VAR Prev = CALCULATE(SELECTEDMEASURE(), SAMEPERIODLASTYEAR(Dates[Date]))\n  RETURN DIVIDE(Curr - Prev, Prev)\n  -- FormatString: \"0.0%;-0.0%\"\n\n\n-- Calculation Group 2: Currency (Precedence: 20)\nUSD:\n  SELECTEDMEASURE()\n  -- FormatString: \"$#,0\"\n\nEUR:\n  SELECTEDMEASURE() * 0.92\n  -- FormatString: \"€#,0\"\n\nGBP:\n  SELECTEDMEASURE() * 0.79\n  -- FormatString: \"£#,0\"\n\n\n-- Combined behavior in a Matrix:\n-- Rows: Products\n-- Columns: Time Calc[Period] (YTD, PY)\n-- Filter: Currency[Selection] = EUR\n-- Result: YTD Sales in EUR = TOTALYTD(SUM * 0.92)',
    ['Time group applies to any measure','Currency group converts correctly','Both groups combine properly','Format strings adapt per selection'],'Calculation groups are Power BI\'s most powerful feature — they turn N measures × M transformations into N + M definitions.'),

  pbi(9,'data-modeling','Data Modeling & Relationships','Field Parameters & Dynamic Visuals',['Create field parameters for axis switching','Build dynamic measures with field parameters','Combine with slicers for user control'],['Create a field parameter with 3-5 measures','Place parameter on a chart axis','Add the parameter slicer','Create a dimension field parameter','Enable switching between chart breakdowns','Combine measure + dimension parameters','Test all combinations'],
    'Field parameters let users switch what a visual shows without needing multiple visuals. Create once, users choose at runtime.',
    '-- Modeling → New → Field Parameter\n-- Name: "Metric Selector"\n-- Fields: [Total Sales], [Total Profit], [Order Count]\n-- Creates a disconnected table + measure',
    'Dynamic visual with field parameters.',
    '-- Create via: Modeling → New Parameter → Fields\n\n-- Measure Parameter: "Select Metric"\nSelect Metric = {\n  ("Revenue", NAMEOF(Sales[Total Sales]), 0),\n  ("Profit", NAMEOF(Sales[Total Profit]), 1),\n  ("Orders", NAMEOF(Sales[Order Count]), 2),\n  ("Margin %", NAMEOF(Sales[Profit Margin %]), 3)\n}\n\n-- Dimension Parameter: "Analyze By"\nAnalyze By = {\n  ("Region", NAMEOF(Dim_Store[Region]), 0),\n  ("Category", NAMEOF(Dim_Product[Category]), 1),\n  ("Segment", NAMEOF(Dim_Customer[Segment]), 2),\n  ("Month", NAMEOF(Dim_Date[MonthName]), 3)\n}\n\n-- Usage in visual:\n-- Y-axis: Select Metric (from parameter)\n-- X-axis: Analyze By (from parameter)\n-- Slicers: Select Metric, Analyze By\n-- Result: User chooses what to see!\n\n-- Combined with conditional formatting:\nMetric Color = \n  SWITCH(\n    SELECTEDVALUE(\'Select Metric\'[Select Metric Fields]),\n    NAMEOF(Sales[Total Sales]), "#7C6BF0",\n    NAMEOF(Sales[Total Profit]), "#2a9d8f",\n    NAMEOF(Sales[Order Count]), "#54A0FF",\n    "#f8f9fb"\n  )',
    ['Measure parameter switches Y-axis','Dimension parameter switches X-axis','All combinations produce valid charts','Slicer controls visual content'],'Field parameters put the user in control — one visual serves many questions.'),

  pbi(10,'data-modeling','Data Modeling & Relationships','Model Documentation & Best Practices',['Document the data model comprehensively','Create a model diagram','Establish naming conventions'],['Export model metadata','Create entity-relationship diagram','Document each table purpose and grain','List all measures with descriptions','Document RLS roles','Create a change log','Generate a data dictionary'],
    'A model nobody can understand is a model nobody will maintain. Document the why, not just the what.',
    '-- Model Documentation Template:\n-- 1. Model Overview (purpose, grain, refresh)\n-- 2. Table Descriptions (fact vs dim, row count)\n-- 3. Relationship Map (diagram)\n-- 4. Measure Library (grouped by category)\n-- 5. RLS Roles (who sees what)',
    'Complete model documentation template.',
    '-- MODEL DOCUMENTATION: Sales Analytics\n-- Version: 2.1 | Last Updated: 2025-06-15\n-- Owner: BI Team | Refresh: Daily 6:00 AM UTC\n\n== OVERVIEW ==\nPurpose: Sales performance tracking and forecasting\nGrain: One row per order line item\nHistory: 3 years rolling\nRLS: Regional managers see their region only\n\n== TABLES ==\nFact_Sales (Import, 2.4M rows, Daily refresh)\n  Grain: Order line item\n  Keys: DateKey, ProductKey, CustomerKey, StoreKey\n  Measures: Quantity, UnitPrice, Discount, TotalAmount, COGS\n\nDim_Date (Import, 1,096 rows, Static)\n  Range: 2024-01-01 to 2026-12-31\n  Fiscal Year Start: July\n  Marked as Date Table: Yes\n\nDim_Product (Import, 487 rows, Daily refresh)\n  Hierarchy: Category > SubCategory > Product\n  SCD Type: 1 (overwrite)\n\n== KEY MEASURES ==\nTotal Sales = SUM(Fact_Sales[TotalAmount])\nProfit Margin % = DIVIDE([Total Profit], [Total Sales], 0)\nSales YTD = TOTALYTD([Total Sales], Dates[Date])\nYoY Growth = DIVIDE([Total Sales] - [Sales PY], [Sales PY], 0)\n\n== RLS ROLES ==\nRegional Access: Dynamic via Security_UserRegion table\nExecutive: No restrictions (ALL regions)\n\n== CHANGE LOG ==\n2025-06-15: Added Dim_Store, StoreKey to fact\n2025-05-01: Implemented SCD Type 2 on Dim_Customer\n2025-04-15: Initial model release',
    ['Every table documented with grain','All measures have descriptions','RLS documented','Change log maintained'],'Documentation is a gift to your future self — the model you built 6 months ago is a stranger.'),

  // ── Power BI Service & Administration (10 lessons) ────────────────────
  pbi(1,'service-admin','Power BI Service & Administration','Workspace Management',['Create and organize workspaces','Configure workspace roles','Set up workspace governance'],['Create a workspace for each project/team','Set naming convention: [Team]-[Environment]','Assign roles: Admin, Member, Contributor, Viewer','Configure workspace settings (license, OneDrive)','Create workspace for Development and Production','Set up workspace access reviews','Document workspace inventory'],
    'Workspaces are containers for dashboards, reports, datasets, and dataflows. Use separate workspaces for Dev and Prod.',
    '-- Workspace Naming: [Dept]-[Project]-[Env]\n-- Example: Finance-BudgetReports-Dev\n--          Finance-BudgetReports-Prod\n-- Roles: Admin=IT, Member=Developers, Viewer=Business',
    'Workspace governance framework.',
    '-- Workspace Governance Framework:\n\n1. NAMING CONVENTION\n   Format: [Department]-[Project]-[Environment]\n   Examples:\n   - Sales-Pipeline-Dev\n   - Sales-Pipeline-Prod\n   - Finance-Budget-Dev\n   - Finance-Budget-Prod\n   - Executive-KPIs-Prod (no dev for simple reports)\n\n2. ROLE ASSIGNMENTS\n   Admin: BI Team Lead, IT Admin\n   Member: Report developers (can publish)\n   Contributor: Analysts (can edit existing)\n   Viewer: Business users (read-only)\n\n3. LIFECYCLE\n   - Request workspace via IT ticket\n   - Approved by BI Team Lead\n   - Created with standard settings\n   - Reviewed quarterly for usage\n   - Archived after 6 months inactive\n\n4. SETTINGS\n   - License: Premium Per User or Premium Capacity\n   - OneDrive: Connected to team SharePoint\n   - Contact list: BI team email\n   - Sensitivity label: Internal/Confidential\n\n5. MONITORING\n   - Usage metrics app installed\n   - Monthly: active users, report views\n   - Quarterly: access review, cleanup',
    ['Workspaces follow naming convention','Roles assigned per principle of least privilege','Dev/Prod separation enforced','Access review scheduled'],'Workspace governance prevents the chaos of 200 ungoverned workspaces — start organized, stay organized.'),

  pbi(2,'service-admin','Power BI Service & Administration','Scheduled Refresh & Gateway Setup',['Configure scheduled refresh','Install and manage data gateway','Troubleshoot refresh failures'],['Install On-premises Data Gateway','Register gateway in Power BI Service','Add data source credentials to gateway','Configure scheduled refresh (4x daily)','Set up refresh failure notifications','Test refresh manually','Monitor refresh history'],
    'On-premises gateway bridges your local data sources (SQL, files) to the Power BI cloud service. Standard gateway for shared use, Personal for one user.',
    '-- Gateway Setup:\n-- 1. Install on server with data source access\n-- 2. Register in Power BI Admin Portal\n-- 3. Add data sources with credentials\n-- 4. Map dataset to gateway in Service\n-- 5. Schedule refresh times',
    'Complete gateway and refresh configuration.',
    '-- Data Gateway Configuration:\n\n1. INSTALLATION\n   - Download from powerbi.microsoft.com\n   - Install on server (NOT developer laptop)\n   - Server must be: always-on, has data source access\n   - Sign in with Power BI admin account\n   - Name: "Corp-DataGateway-01"\n\n2. DATA SOURCE REGISTRATION\n   Settings → Manage Gateways → Add Data Source:\n   - SQL Server: server=prod-sql, db=Sales, Windows Auth\n   - File Share: \\\\fileserver\\reports\\*.xlsx\n   - Oracle: connection string + credentials\n\n3. SCHEDULED REFRESH\n   Dataset Settings → Scheduled Refresh:\n   - Refresh frequency: 4x daily\n   - Times: 06:00, 10:00, 14:00, 18:00 (UTC)\n   - Gateway: Corp-DataGateway-01\n   - Send failure notification to: bi-team@company.com\n\n4. TROUBLESHOOTING\n   - Check gateway service is running (Windows Services)\n   - Check gateway logs: C:\\Users\\GatewayUser\\AppData\n   - Common errors:\n     - Credential expired → update in Service\n     - Timeout → increase in gateway config\n     - Memory → upgrade server RAM\n\n5. MONITORING\n   - Admin Portal → Gateway Clusters\n   - Track: successful/failed refreshes\n   - Alert on 2+ consecutive failures\n   - Monthly: review refresh duration trends',
    ['Gateway installed and registered','Data source credentials configured','Refresh runs 4x daily successfully','Failure notifications active'],'A missed refresh means stale data — and stale data erodes trust in the entire BI platform.'),

  pbi(3,'service-admin','Power BI Service & Administration','App Publishing & Distribution',['Create and publish a Power BI App','Configure app audiences','Manage app updates'],['Group reports into an app','Set app navigation structure','Configure audience access groups','Publish the app','Update the app with new reports','Set up automatic installation','Communicate app URL to users'],
    'Apps are curated collections of reports for business users. They provide a cleaner experience than workspace access. Audiences let you show different content to different groups.',
    '-- App Configuration:\n-- Name: "Sales Performance"\n-- Navigation: Overview | Regional | Products | Forecast\n-- Audience 1: All Sales → sees all pages\n-- Audience 2: Regional Managers → sees Regional page only',
    'App publishing workflow.',
    '-- Power BI App Publishing:\n\n1. PREPARATION\n   - All reports finalized and tested\n   - Dashboard created (optional, for pinned tiles)\n   - Navigation order decided\n   - App icon and description ready\n\n2. CONFIGURATION\n   Workspace → Create App:\n   Setup:\n     Name: "Sales Performance Hub"\n     Description: "Weekly sales metrics and forecasts"\n     App logo: company_logo.png\n     Contact: bi-team@company.com\n   Navigation:\n     1. Executive Summary (report page)\n     2. Regional Breakdown (report page)\n     3. Product Analysis (report page)\n     4. Forecast (report page)\n     5. Data Dictionary (link to SharePoint)\n   Access:\n     Audience 1: "All Sales" → all pages\n       AD Group: SG-PowerBI-Sales-All\n     Audience 2: "Regional Only" → pages 1,2\n       AD Group: SG-PowerBI-Sales-Regional\n\n3. PUBLISH\n   - Click Publish App\n   - Share app URL: app.powerbi.com/apps/[guid]\n   - Enable: Install app automatically (for target groups)\n\n4. UPDATES\n   - Edit reports in workspace\n   - Update App → review changes → Publish\n   - Users get updated automatically\n   - No action needed by consumers',
    ['App published with custom navigation','Audiences configured per group','Auto-install enabled','App URL distributed'],'Apps are how business users consume Power BI — workspaces are for developers, apps are for everyone else.'),

  pbi(4,'service-admin','Power BI Service & Administration','Dataflows for Reusable ETL',['Create dataflows in Power BI Service','Share prepared data across datasets','Build a gold layer with dataflows'],['Create a dataflow in workspace','Add entities from SQL/CSV sources','Apply Power Query transformations','Schedule dataflow refresh','Connect a dataset to the dataflow','Share dataflow across workspaces','Monitor dataflow refresh health'],
    'Dataflows are Power Query in the cloud — prepare data once, reuse across multiple datasets. Think of them as a shared ETL layer.',
    '-- Dataflow Architecture:\n-- Raw Sources → Dataflow (clean & transform) → Datasets → Reports\n-- One dataflow serves multiple datasets\n-- Canonical: Dim_Customer, Dim_Product, Fact_Sales',
    'Dataflow architecture for enterprise reuse.',
    '-- Enterprise Dataflow Architecture:\n\n1. BRONZE LAYER (Raw Staging)\n   Dataflow: "Raw-Sources"\n   - Raw_SQL_Sales: direct copy from SQL\n   - Raw_Excel_Budget: direct copy from SharePoint\n   - Raw_API_CRM: direct copy from REST API\n   - Refresh: 4x daily, 15 min before gold layer\n\n2. GOLD LAYER (Cleaned & Modeled)\n   Dataflow: "Gold-Canonical"\n   - Dim_Date: generated date table\n   - Dim_Product: cleaned, enriched from Raw_SQL\n   - Dim_Customer: SCD Type 1 from Raw_CRM\n   - Fact_Sales: joined, typed from Raw_SQL_Sales\n   - Refresh: 4x daily, after bronze completes\n   - Linked entity from Bronze (not duplicated)\n\n3. CONSUMPTION\n   Dataset: "Sales Analytics"\n   - Connects to Gold-Canonical dataflow\n   - Import mode (cached for performance)\n   - Adds measures, calculation groups\n   - Refresh: after Gold completes\n\n4. BENEFITS\n   - Dim_Customer defined ONCE, used in 5 datasets\n   - Change customer logic in dataflow → all datasets updated\n   - IT controls the gold layer\n   - Analysts build reports without raw data access\n\n5. GOVERNANCE\n   - Dataflow owner: BI Team\n   - Certification: mark gold entities as "Certified"\n   - Documentation: describe each entity in dataflow settings',
    ['Bronze and Gold layers separated','Entities reused across datasets','Refresh chain configured correctly','Certified entities marked'],'Dataflows are the single source of truth layer — define dimensions once, reuse everywhere.'),

  pbi(5,'service-admin','Power BI Service & Administration','Deployment Pipelines',['Set up Dev → Test → Prod pipeline','Configure deployment rules','Automate deployment approvals'],['Create deployment pipeline','Assign workspaces to stages','Deploy from Dev to Test','Configure data source rules for Test','Deploy from Test to Prod','Set up deployment rules for connection changes','Document release process'],
    'Deployment pipelines provide CI/CD for Power BI. Each stage has its own workspace. Deployment rules change connection strings per environment.',
    '-- Pipeline: Sales Reports\n-- [Dev Workspace] → Deploy → [Test Workspace] → Deploy → [Prod Workspace]\n-- Rules: SQL server changes per stage',
    'Deployment pipeline with automation.',
    '-- Deployment Pipeline Setup:\n\n1. CREATE PIPELINE\n   Admin Portal → Deployment Pipelines → Create\n   Name: "Sales Reports Pipeline"\n\n2. ASSIGN WORKSPACES\n   Development: Sales-Reports-Dev\n   Test: Sales-Reports-Test\n   Production: Sales-Reports-Prod\n\n3. DEPLOYMENT RULES (per stage)\n   Test stage:\n   - Data source: server=test-sql → test-sql.company.com\n   - Parameter: Environment → "Test"\n   Test stage:\n   - Data source: server=prod-sql → prod-sql.company.com\n   - Parameter: Environment → "Production"\n\n4. DEPLOYMENT WORKFLOW\n   a. Developer publishes to Dev workspace\n   b. Review changes in pipeline (diff view)\n   c. Deploy Dev → Test\n   d. QA tests in Test workspace\n   e. Deploy Test → Prod (requires approval)\n   f. Verify refresh in Prod\n\n5. RELEASE CHECKLIST\n   [ ] All DAX measures verified in Dev\n   [ ] Refresh tested with Dev credentials\n   [ ] Deploy to Test → QA sign-off\n   [ ] RLS tested in Test\n   [ ] Performance acceptable (<5s load)\n   [ ] Deploy to Prod\n   [ ] Prod refresh verified\n   [ ] Stakeholder notified',
    ['3-stage pipeline configured','Deployment rules swap connections','QA sign-off before Prod','Release checklist followed'],'Deployment pipelines are non-negotiable for enterprise BI — never publish directly to production.'),

  pbi(6,'service-admin','Power BI Service & Administration','Capacity Management & Premium',['Understand Premium vs Pro licensing','Monitor capacity utilization','Optimize workload distribution'],['Review current license allocation','Check capacity utilization in Admin Portal','Identify heavy datasets consuming resources','Configure max memory per dataset','Set up autoscale rules','Monitor background operations','Plan capacity for growth'],
    'Premium capacity is a dedicated resource pool. Monitor CPU, memory, and active operations. Overloaded capacity = slow reports for everyone.',
    '-- Capacity Metrics:\n-- CPU: 80% sustained = overloaded\n-- Memory: >80% dataset evictions\n-- Active operations: queue depth > 10 = backlog',
    'Capacity monitoring and optimization.',
    '-- Premium Capacity Management:\n\n1. CAPACITY TYPES\n   P1: 8 cores, 25GB RAM (~$5K/mo)\n   P2: 16 cores, 50GB RAM (~$10K/mo)\n   EM1-EM3: Embedded (API access)\n   PPU: Per-user (~$20/user/mo)\n\n2. MONITORING (Admin Portal → Capacity Settings)\n   Key Metrics:\n   - CPU utilization: target <70% sustained\n   - Memory: target <80% (avoid evictions)\n   - Active refreshes: target <5 concurrent\n   - Query duration: p95 < 30 seconds\n\n3. OPTIMIZATION\n   a. Reduce dataset sizes (VertiPaq optimization)\n   b. Stagger refresh schedules (avoid peak)\n   c. Use incremental refresh for large datasets\n   d. Move low-priority workloads to off-peak\n   e. Enable query caching for popular reports\n   f. Consider composite models to reduce memory\n\n4. AUTOSCALE\n   Settings → Autoscale:\n   - Enable: Yes\n   - Max additional v-cores: 2\n   - Trigger: CPU > 80% for 5 minutes\n   - Cost: billed per v-core-hour\n\n5. COST ALLOCATION\n   - Tag workspaces to cost centers\n   - Monthly: top 10 datasets by resource\n   - Review: can any datasets move to Pro?',
    ['Capacity utilization < 70% CPU','No dataset evictions','Refresh schedule staggered','Autoscale configured'],'Capacity management is infrastructure management — treat it like you would server provisioning.'),

  pbi(7,'service-admin','Power BI Service & Administration','Usage Metrics & Adoption Tracking',['Track report and dataset usage','Identify adoption patterns','Create an adoption dashboard'],['Install Usage Metrics report template','Review top reports by views','Identify unused reports for archival','Track unique viewers over time','Create adoption KPIs: MAU, DAU, report/user','Set up weekly usage email to stakeholders','Plan training based on low-adoption areas'],
    'If you don\'t measure adoption, you don\'t know if your BI investment is working. Track: active users, report views, and which content is actually used.',
    '-- Key Adoption Metrics:\n-- Monthly Active Users (MAU)\n-- Reports per user per month\n-- Dataset refresh success rate\n-- Time to first report (new users)',
    'BI adoption tracking framework.',
    '-- BI Adoption Dashboard Metrics:\n\n1. ENGAGEMENT\n   - MAU: Monthly Active Users (target: 80% of licensed)\n   - DAU/MAU ratio: daily engagement (target: >30%)\n   - Report Views/User/Month (target: >10)\n   - Session Duration: avg time in reports\n\n2. CONTENT HEALTH\n   - Reports: total, active (viewed in 30d), stale\n   - Datasets: total, refreshing, failed\n   - Workspaces: total, active, orphaned\n   - Apps: published, installed, used\n\n3. QUALITY\n   - Refresh success rate (target: >99%)\n   - Avg query time (target: <5s)\n   - Report errors per week\n   - Support tickets per 100 users\n\n4. GROWTH\n   - New users this month\n   - New reports published\n   - Self-service vs IT-built reports\n   - Training attendance\n\n5. COST EFFICIENCY\n   - Cost per active user per month\n   - Premium utilization rate\n   - Unused licenses\n   - ROI: decisions influenced by data\n\n6. ACTION TRIGGERS\n   - MAU drop >10%: email department heads\n   - Report unused 60d: notify owner, archive at 90d\n   - Refresh failure 3x: escalate to IT\n   - New user: auto-enroll in training path',
    ['MAU tracked monthly','Unused reports identified','Refresh success >99%','Training needs documented'],'Adoption is the ultimate KPI for a BI team — a report nobody uses has zero value regardless of how beautiful it is.'),

  pbi(8,'service-admin','Power BI Service & Administration','Embedding Power BI',['Understand embed scenarios','Implement "Embed for your organization"','Set up "Embed for your customers"'],['Choose embed type: org vs customers','Register an Azure AD application','Get workspace and report IDs','Generate embed token','Create an HTML page with Power BI JS SDK','Handle authentication flow','Test embedded report with filters'],
    'Embed for org uses user\'s own Power BI license. Embed for customers uses a service principal — the user doesn\'t need a Power BI account.',
    '// Embed for organization (User owns data)\nvar embedConfig = {\n  type: "report",\n  id: reportId,\n  embedUrl: embedUrl,\n  accessToken: userToken\n};',
    'Complete embedding implementation.',
    '// Power BI Embedding: App Owns Data (Embed for Customers)\n\n// 1. Server-side: Generate embed token\nconst { ClientSecretCredential } = require("@azure/identity");\nconst { PowerBIClient } = require("@azure/arm-powerbiembedded");\n\nconst credential = new ClientSecretCredential(\n  tenantId, clientId, clientSecret\n);\n\nasync function getEmbedToken(workspaceId, reportId) {\n  const tokenRequest = {\n    reports: [{ id: reportId }],\n    datasets: [{ id: datasetId }],\n  };\n  // POST to Power BI REST API\n  const response = await fetch(\n    `https://api.powerbi.com/v1.0/myorg/groups/${workspaceId}/reports/${reportId}/GenerateToken`,\n    {\n      method: "POST",\n      headers: {\n        "Authorization": `Bearer ${accessToken}`,\n        "Content-Type": "application/json"\n      },\n      body: JSON.stringify({ accessLevel: "View" })\n    }\n  );\n  return response.json(); // { token, expiration }\n}\n\n// 2. Client-side: Embed the report\n// <div id="report-container"></div>\n// <script src="https://cdn.jsdelivr.net/npm/powerbi-client/dist/powerbi.min.js"></script>\n\nvar models = window["powerbi-client"].models;\nvar config = {\n  type: "report",\n  id: reportId,\n  embedUrl: embedUrl,\n  accessToken: embedToken,\n  tokenType: models.TokenType.Embed,\n  settings: {\n    navContentPaneEnabled: false,\n    filterPaneEnabled: false\n  }\n};\nvar report = powerbi.embed(\n  document.getElementById("report-container"), config\n);',
    ['Embed token generated server-side','Report renders in HTML page','Filters work in embedded view','Authentication flow secure'],'Embedding puts Power BI inside your app — your users get insights without leaving their workflow.'),

  pbi(9,'service-admin','Power BI Service & Administration','Governance Framework & Tenant Settings',['Design a governance framework','Configure tenant admin settings','Establish data classification'],['Review all tenant settings in Admin Portal','Disable export to file for external sharing','Enable certified content promotion','Set up sensitivity labels integration','Create governance policy document','Assign governance roles','Schedule quarterly governance review'],
    'Tenant settings control what every user can do. Start restrictive and open up per group — never start open and try to restrict later.',
    '-- Key Tenant Settings:\n-- Export data: Restricted to security group\n-- Publish to web: Disabled (public = no auth)\n-- External sharing: Restricted to approved domains\n-- Certification: Enabled, only BI team can certify',
    'Complete governance framework.',
    '-- Power BI Governance Framework:\n\n1. TENANT SETTINGS (Admin Portal)\n   Export & Sharing:\n   ✗ Publish to web: DISABLED (public, no auth)\n   ✓ Export to Excel: BI-Users group only\n   ✓ Export to PDF: All users\n   ✗ External sharing: Approved domains only\n\n   Content:\n   ✓ Certification: BI-Admins can certify\n   ✓ Endorsement: All Pro users can promote\n   ✓ Featured content: BI-Admins only\n\n   Developer:\n   ✓ Embed for organization: All\n   ✓ Embed for customers: BI-Admins only\n   ✓ Service principals: Approved apps only\n\n2. DATA CLASSIFICATION\n   Public: aggregated, non-sensitive\n   Internal: company data, not PII\n   Confidential: PII, financial details\n   Restricted: board materials, M&A\n\n3. SENSITIVITY LABELS\n   - Integrate with Microsoft Purview\n   - Auto-label datasets with PII columns\n   - Prevent export of Confidential data\n   - Audit label changes\n\n4. GOVERNANCE ROLES\n   Data Steward: defines data quality rules\n   BI Admin: manages tenant settings\n   Report Owner: responsible for accuracy\n   Certifier: validates content quality\n\n5. REVIEW CADENCE\n   Monthly: usage metrics, failed refreshes\n   Quarterly: access reviews, license audit\n   Annually: governance policy update',
    ['Tenant settings reviewed and configured','Publish-to-web disabled','Certification process established','Sensitivity labels integrated'],'Governance is not bureaucracy — it is the immune system that keeps your BI platform healthy.'),

  pbi(10,'service-admin','Power BI Service & Administration','Admin API & Automation',['Use Power BI REST API for automation','Automate workspace inventory','Build operational monitoring'],['Get Azure AD token for Power BI API','List all workspaces via API','Get dataset refresh history','Automate user license reporting','Create a refresh monitoring script','Schedule via Azure Functions or Power Automate','Build an operational health dashboard'],
    'The Power BI REST API lets you automate everything you can do in the portal. Use it for inventory, monitoring, and governance at scale.',
    '# List all workspaces\ncurl -H "Authorization: Bearer $token" \\\n  "https://api.powerbi.com/v1.0/myorg/groups" | jq ".value[].name"',
    'Automated Power BI admin monitoring.',
    '# Power BI Admin Automation (Python)\nimport requests\nimport pandas as pd\nfrom datetime import datetime, timedelta\n\nBASE = "https://api.powerbi.com/v1.0/myorg"\nHEADERS = {"Authorization": f"Bearer {access_token}"}\n\ndef get_workspaces():\n    r = requests.get(f"{BASE}/groups", headers=HEADERS)\n    return pd.DataFrame(r.json()["value"])\n\ndef get_refresh_history(dataset_id, group_id):\n    url = f"{BASE}/groups/{group_id}/datasets/{dataset_id}/refreshes"\n    r = requests.get(url, headers=HEADERS)\n    return pd.DataFrame(r.json()["value"])\n\ndef get_datasets(group_id):\n    r = requests.get(f"{BASE}/groups/{group_id}/datasets", headers=HEADERS)\n    return pd.DataFrame(r.json()["value"])\n\n# Build health report\nworkspaces = get_workspaces()\nprint(f"Total workspaces: {len(workspaces)}")\n\nfailures = []\nfor _, ws in workspaces.iterrows():\n    datasets = get_datasets(ws["id"])\n    for _, ds in datasets.iterrows():\n        history = get_refresh_history(ds["id"], ws["id"])\n        if len(history) > 0:\n            latest = history.iloc[0]\n            if latest.get("status") == "Failed":\n                failures.append({\n                    "workspace": ws["name"],\n                    "dataset": ds["name"],\n                    "error": latest.get("serviceExceptionJson", "Unknown"),\n                    "time": latest.get("endTime")\n                })\n\nprint(f"\\nFailed refreshes: {len(failures)}")\nfor f in failures:\n    print(f"  {f[\'workspace\']}/{f[\'dataset\']}: {f[\'error\'][:80]}")',
    ['API authentication works','Workspace inventory generated','Failed refreshes detected','Script runs on schedule'],'Automate admin tasks with the API — manual governance doesn\'t scale past 50 workspaces.'),
];
